INSERT INTO mandates (dept_id, item_order, content) VALUES ('001', 1, 'ปฏิบัติงานธุรการ อำนวยการ ส่งเสริม และสนับสนุนเพื่อให้คณะกรรมการตรวจเงินแผ่นดินบรรลุภารกิจและหน้าที่ตามที่กฎหมายกำหนด');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('001', 2, 'ดำเนินการเกี่ยวกับการประชุมคณะกรรมการตรวจเงินแผ่นดิน ประสานงาน รวบรวมข้อมูลที่เกี่ยวข้องกับการนำเสนอต่อที่ประชุมคณะกรรมการตรวจเงินแผ่นดิน รวมทั้งประสานงานการติดตามผล และการเผยแพร่ผลการประชุมตามมติคณะกรรมการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('001', 3, 'ดำเนินการเกี่ยวกับการประชุมพิจารณาวินิจฉัยความผิดวินัยการเงินการคลังของรัฐของคณะกรรมการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('001', 4, 'จัดทำคำของบประมาณ จัดทำแผนการดำเนินงาน รวมถึงจัดการเกี่ยวกับสิทธิประโยชน์ของคณะกรรมการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('001', 5, 'ติดตามการจัดทำรายงานผลการปฏิบัติงานประจำปี และรายงานผลการปฏิบัติงานระหว่างปีของสำนักงานการตรวจเงินแผ่นดิน เพื่อเสนอคณะกรรมการตรวจเงินแผ่นดินพิจารณาให้ความเห็นชอบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('001', 6, 'ดำเนินการเกี่ยวกับงานนิเทศ งานตรวจเยี่ยม งานรัฐพิธี และพิธีการต่าง ๆ ให้กับคณะกรรมการตรวจเงินแผ่นดิน และประสานงานกับส่วนราชการภายในและภายนอก รวมทั้งองค์กร สถาบัน และหน่วยงานต่าง ๆ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('001', 7, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('001', 8, 'ปฏิบัติหน้าที่อื่นตามที่คณะกรรมการตรวจเงินแผ่นดิน หรือผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('002', 1, 'ปฏิบัติงานธุรการ งานอำนวยการ และงานเลขานุการของผู้ว่าการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('002', 2, 'ดำเนินการเกี่ยวกับงานนิเทศ งานตรวจเยี่ยม งานรัฐพิธี และพิธีการต่าง ๆ ให้กับผู้ว่าการตรวจเงินแผ่นดินและสำนักงานการตรวจเงินแผ่นดิน และประสานงานกับส่วนราชการภายในและภายนอก รวมทั้งองค์กร สถาบัน และหน่วยงานต่าง ๆ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('002', 3, 'ประสานราชการกับหน่วยงานของรัฐ รัฐบาล รัฐสภา บุคคล หรือหน่วยงานที่เกี่ยวข้องทั้งภายในและภายนอกเพื่อสนับสนุนการปฏิบัติงานตามภารกิจของผู้ว่าการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('002', 4, 'กลั่นกรองเรื่องที่จะนำเข้าสู่การพิจารณาของผู้ว่าการตรวจเงินแผ่นดิน และติดตามผลการดำเนินงานในเรื่องที่ผู้ว่าการตรวจเงินแผ่นดินสั่งการหรือมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('002', 5, 'ดำเนินการเกี่ยวกับการประชุมคณะผู้บริหารของสำนักงานการตรวจเงินแผ่นดินการประชุมองค์กรอิสระเพื่อบูรณาการการทำงาน การประชุมคณะทำงานหรือคณะกลั่นกรองงานที่ผู้ว่าการตรวจเงินแผ่นดินแต่งตั้ง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('002', 6, 'ติดตามและประสานงานกับส่วนราชการภายในและภายนอกที่เกี่ยวข้องในเรื่องที่จะนำเสนอเข้าสู่การพิจารณาของคณะผู้บริหารของสำนักงานการตรวจเงินแผ่นดิน และการปฏิบัติตามมติของที่ประชุมคณะผู้บริหารของสำนักงานการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('002', 7, 'อำนวยการ สนับสนุน ช่วยเหลือการดำเนินการตามหน้าที่และอำนาจของผู้ว่าการตรวจเงินแผ่นดินให้เป็นไปตามกฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน รวมถึงประสานราชการทั้งภายในและภายนอกกับบุคคลหรือหน่วยงานที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('002', 8, 'ติดตามงานตรวจสอบ งานของคณะกรรมการตรวจเงินแผ่นดินที่สำนักงานการตรวจเงินแผ่นดินจะต้องดำเนินการ รวมถึงความคืบหน้าของการดำเนินการ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('002', 9, 'ติดตามงานและเรื่องร้องเรียนที่สำนักงานการตรวจเงินแผ่นดินจะต้องดำเนินการตามกฎหมายแล้วรายงานให้ผู้ว่าการตรวจเงินแผ่นดินทราบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('002', 10, 'ดำเนินการเกี่ยวกับงานธุรการ และงานเลขานุการของผู้บริหารสำนักงานการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('002', 11, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('002', 12, 'ปฏิบัติหน้าที่อื่นตามที่คณะกรรมการตรวจเงินแผ่นดิน หรือผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('003', 1, 'ศึกษากรณีที่สมควรให้คำปรึกษา แนะนำ เกี่ยวกับการใช้จ่ายเงินแผ่นดินตามที่คณะกรรมการตรวจเงินแผ่นดินมอบหมาย เพื่อให้เป็นไปตามกฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ รวมทั้งกรณีที่ควรให้คำแนะนำแก่หน่วยงานของรัฐในการแก้ไขข้อบกพร่องเกี่ยวกับการใช้จ่ายเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('003', 2, 'เสนอความเห็นและข้อเสนอแนะต่อผู้ว่าการตรวจเงินแผ่นดิน เพื่อเสนอต่อคณะกรรมการตรวจเงินแผ่นดินเพื่อให้คำปรึกษา แนะนำ หรือเสนอแนะเกี่ยวกับการใช้จ่ายเงินแผ่นดินให้เป็นไปตามกฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ รวมทั้งกรณีที่ควรให้คำแนะนำแก่หน่วยงานของรัฐในการแก้ไขข้อบกพร่องเกี่ยวกับการใช้จ่ายเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('003', 3, 'ศึกษา วิเคราะห์ จัดทำ และติดตามผลผลิตของงานที่เสริมสร้างความเข้มแข็งให้กับงานตรวจสอบ (Non - Audit Product) ตามนโยบายการตรวจเงินแผ่นดิน และเสนอความเห็นต่อผู้ว่าการตรวจเงินแผ่นดิน เพื่อเสนอต่อคณะกรรมการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('003', 4, 'รวบรวม และรับเรื่องจากส่วนราชการภายในอื่นที่เสนอเรื่องกรณีที่สมควรเสนอต่อคณะกรรมการตรวจเงินแผ่นดินเพื่อให้คำปรึกษา แนะนำ หรือเสนอแนะเกี่ยวกับการใช้จ่ายเงินแผ่นดินให้เป็นไปตามกฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ รวมทั้งกรณีที่ควรให้คำแนะนำแก่หน่วยงานของรัฐในการแก้ไขข้อบกพร่องเกี่ยวกับการใช้จ่ายเงินแผ่นดิน และกรณีที่เกี่ยวกับการจัดทำผลผลิตของงานที่เสริมสร้างความเข้มแข็งให้กับงานตรวจสอบ (Non - Audit Product) เพื่อดำเนินตามข้อ ๒) หรือข้อ ๓) ต่อไป');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('003', 5, 'กลั่นกรองงานเพื่อเสนอคณะกรรมการตรวจเงินแผ่นดินพิจารณาตามที่ได้รับมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('003', 6, 'พิจารณาให้ความเห็นข้อกฎหมายและให้บริการข้อมูลทางด้านวิชาการแก่ผู้ว่าการตรวจเงินแผ่นดิน และคณะกรรมการตรวจเงินแผ่นดิน ตามที่ได้รับมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('003', 7, 'เสนอร่าง กลั่นกรอง หรือแก้ไขกฎ ระเบียบ หลักเกณฑ์ และคำสั่ง ตามหน้าที่และอำนาจของผู้ว่าการตรวจเงินแผ่นดิน และคณะกรรมการตรวจเงินแผ่นดิน ตามที่ได้รับมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('003', 8, 'รวบรวมและจัดทำรายงานผลการวิเคราะห์ข้อมูลที่หน่วยงานของรัฐดำเนินการด้วยวิธีการทางอิเล็กทรอนิกส์ผ่านระบบการเปิดเผยข้อมูลทางอิเล็กทรอนิกส์ตามที่คณะกรรมการตรวจเงินแผ่นดินประกาศกำหนดเกี่ยวกับการที่หน่วยงานของรัฐใช้จ่ายเงินหรือทรัพย์สินให้สื่อมวลชน ตามมาตรา ๓๕ ของรัฐธรรมนูญแห่งราชอาณาจักรไทย พุทธศักราช ๒๕๖๐');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('003', 9, 'ประสานงานเพื่อการให้ความร่วมมือและความช่วยเหลือองค์กรอิสระอื่น');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('003', 10, 'เสนอความเห็นเพื่อประกอบการพิจารณาของคณะกรรมการตรวจเงินแผ่นดินในการระงับยับยั้งความเสียหายที่อาจเกิดขึ้นแก่การเงินการคลังของรัฐ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('003', 11, 'ประสานงานกับสถาบันพัฒนาการตรวจเงินแผ่นดินเพื่อเผยแพร่องค์ความรู้ทางกฎหมายที่เกี่ยวข้องกับการตรวจเงินแผ่นดิน รวมถึงเสนอให้มีการศึกษาอบรมจัดหลักสูตรหรือโครงการสำหรับคณะกรรมการตรวจเงินแผ่นดินและบุคลากรของสำนักงานการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('003', 12, 'ปฏิบัติงานร่วมกับหรือประสานงานกับส่วนราชการภายในอื่นที่เกี่ยวข้องเพื่อจัดทำร่างนโยบายการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('003', 13, 'ศึกษาหลักเกณฑ์มาตรฐานที่เกี่ยวกับการตรวจเงินแผ่นดินให้สอดคล้องกับหลักการและมาตรฐานการตรวจเงินแผ่นดินสากล ดำเนินการรับฟังความคิดเห็นของหน่วยรับตรวจในการกำหนดหลักเกณฑ์มาตรฐานที่เกี่ยวกับการตรวจเงินแผ่นดิน และประสานความร่วมมือให้เป็นไปตามนโยบายการตรวจเงินแผ่นดินที่เกี่ยวกับการต่างประเทศ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('003', 14, 'ดำเนินกระบวนการสรรหาบุคคลที่สมควรได้รับการเสนอชื่อเพื่อแต่งตั้งเป็นผู้ว่าการตรวจเงินแผ่นดิน รวมทั้งประสานงานเสนอชื่อบุคคลเป็นกรรมการสรรหาผู้ดำรงตำแหน่งในองค์กรอิสระอื่น');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('003', 15, 'พิจารณาให้ความเห็นเกี่ยวกับการปฏิบัติงานของสำนักงานการตรวจเงินแผ่นดินตามที่คณะกรรมการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('003', 16, 'รวบรวม ประมวล และวิเคราะห์การตอบข้อสอบถามของผู้ว่าการตรวจเงินแผ่นดินหรือเจ้าหน้าที่ที่ได้รับมอบหมายเพื่อเป็นแนวทางการตอบข้อสอบถามของหน่วยรับตรวจที่เกี่ยวกับการปฏิบัติตามกฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน กฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ และเรื่องที่อยู่ในอำนาจการตรวจสอบของผู้ว่าการตรวจเงินแผ่นดิน ให้เป็นมาตรฐานเดียวกัน รวมทั้งข้อสอบถามเกี่ยวกับการใช้จ่ายเงินแผ่นดินที่สมควรเสนอคณะกรรมการตรวจเงินแผ่นดินเพื่อพิจารณาให้คำปรึกษา แนะนำแก่หน่วยงานของรัฐตามกฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('003', 17, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('003', 18, 'ปฏิบัติหน้าที่อื่นตามที่คณะกรรมการตรวจเงินแผ่นดิน หรือผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('004', 1, 'ศึกษา วิเคราะห์ เสนอแนะ และสนับสนุนคณะกรรมการตรวจเงินแผ่นดินหรือกรรมการตรวจเงินแผ่นดินในการกำกับการตรวจเงินแผ่นดินให้เป็นไปตามนโยบายการตรวจเงินแผ่นดิน หลักเกณฑ์มาตรฐานที่เกี่ยวกับการตรวจเงินแผ่นดิน และตามกฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ รวมทั้งศึกษา วิเคราะห์ และดำเนินการยกร่างหรือแก้ไขเพิ่มเติม ระเบียบ ประกาศ หรือข้อบังคับในเรื่องการกำกับการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('004', 2, 'ให้ความเห็นและข้อเสนอแนะในการตรวจเงินแผ่นดินให้เป็นไปตามนโยบายการตรวจเงินแผ่นดิน หลักเกณฑ์มาตรฐานที่เกี่ยวกับการตรวจเงินแผ่นดิน และตามกฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('004', 3, 'ศึกษา วิเคราะห์ พิจารณาให้ความเห็นต่อระเบียบ ข้อบังคับ ประกาศ แผนการปฏิบัติราชการที่เกี่ยวกับการตรวจเงินแผ่นดิน ให้เป็นไปตามนโยบายการตรวจเงินแผ่นดิน หลักเกณฑ์มาตรฐานที่เกี่ยวกับการตรวจเงินแผ่นดิน และตามกฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('004', 4, 'พิจารณาให้ความเห็นต่อสรุปรายงานผลการตรวจเงินแผ่นดินที่ผู้ว่าการตรวจเงินแผ่นดิน จัดทำสรุปเป็นรายไตรมาส พร้อมเสนอความเห็นหรือข้อสังเกตต่อคณะกรรมการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('004', 5, 'ดำเนินการตรวจสอบ รวบรวมข้อเท็จจริงและพยานหลักฐาน และจัดทำร่างผลการตรวจสอบข้อเท็จจริง เพื่อนำเสนอคณะกรรมการตรวจเงินแผ่นดิน ในกรณีที่หน่วยรับตรวจยื่นคำร้องหรือความปรากฏต่อคณะกรรมการตรวจเงินแผ่นดิน ว่าการตรวจสอบไม่เป็นไปตามนโยบายการตรวจเงินแผ่นดิน หรือหลักเกณฑ์มาตรฐานที่เกี่ยวกับการตรวจเงินแผ่นดิน หรือตามกฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('004', 6, 'เสนอเรื่องพร้อมความเห็นต่อคณะกรรมการตรวจเงินแผ่นดินตามที่ผู้ว่าการตรวจเงินแผ่นดินขอปรึกษาหารือ ขอคำแนะนำ หรือข้อเสนอแนะเพื่อใช้ในการแก้ไขปัญหาเกี่ยวกับการปฏิบัติหน้าที่ในการตรวจเงินแผ่นดินตามนโยบายการตรวจเงินแผ่นดิน และหลักเกณฑ์มาตรฐานเกี่ยวกับการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('004', 7, 'ดำเนินการเกี่ยวกับการรับเรื่องการตรวจสอบ การรวบรวมข้อเท็จจริงและพยานหลักฐาน ในกรณีหน่วยรับตรวจเห็นว่าผู้ว่าการตรวจเงินแผ่นดินหรือผู้ที่ได้รับมอบหมายดำเนินการตรวจสอบไม่เป็นไปตามนโยบายการตรวจเงินแผ่นดิน หรือหลักเกณฑ์มาตรฐานที่เกี่ยวกับการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('004', 8, 'อำนวยความสะดวก ช่วยเหลือ ส่งเสริมและสนับสนุนการปฏิบัติงานของคณะกรรมการตรวจเงินแผ่นดิน กรรมการตรวจเงินแผ่นดิน และผู้ว่าการตรวจเงินแผ่นดินในเรื่องที่เกี่ยวกับการกำกับการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('004', 9, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('004', 10, 'ปฏิบัติหน้าที่อื่นตามที่คณะกรรมการตรวจเงินแผ่นดิน หรือผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('005', 1, 'ปฏิบัติงานธุรการ งานอำนวยการ และงานเลขานุการที่เกี่ยวกับการดำเนินการทางวินัยการเงินการคลังของรัฐ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('005', 2, 'สอบทานการเสนอเรื่องความผิดวินัยการเงินการคลังของรัฐ ว่าเป็นไปตามกฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน กฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ นโยบายการตรวจเงินแผ่นดิน และหลักเกณฑ์มาตรฐานที่เกี่ยวกับการตรวจเงินแผ่นดิน รวมทั้งมีข้อเท็จจริงและพฤติการณ์ที่เป็นเหตุอันควรลงโทษทางปกครองพร้อมพยานหลักฐานครบถ้วนสมบูรณ์ พร้อมทั้งให้ข้อเสนอแนะเกี่ยวกับโทษที่สมควรลงโทษ เสนอผู้ว่าการตรวจเงินแผ่นดิน เพื่อเสนอต่อคณะกรรมการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('005', 3, 'ดำเนินการตรวจเรื่องความผิดวินัยการเงินการคลังของรัฐ และเสนอความเห็นต่อคณะกรรมการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('005', 4, 'ดำเนินการแจ้งข้อกล่าวหา รับฟังคำชี้แจงแก้ข้อกล่าวหา รวบรวมข้อเท็จจริงและพยานหลักฐาน และดำเนินการอื่นที่เกี่ยวกับเรื่องความผิดวินัยการเงินการคลังของรัฐ ตามที่คณะกรรมการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('005', 5, 'ดำเนินการสนับสนุนคณะกรรมการตรวจเงินแผ่นดินในการพิจารณาวินิจฉัยชี้ขาดความผิดวินัยการเงินการคลังของรัฐ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('005', 6, 'แจ้งคำวินิจฉัยและดำเนินการอื่น ๆ เพื่อบังคับตามคำวินิจฉัยของคณะกรรมการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('005', 7, 'ดำเนินการเพื่อให้เป็นไปตามคำบังคับของศาลปกครองกรณีพิพากษาให้เพิกถอนคำสั่งทางปกครองหรือคำวินิจฉัยของคณะกรรมการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('005', 8, 'ให้คำปรึกษา แนะนำ และตอบข้อหารือเกี่ยวกับกระบวนพิจารณาความผิดวินัยการเงินการคลังของรัฐ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('005', 9, 'ประชาสัมพันธ์เผยแพร่คำวินิจฉัยความผิดวินัยการเงินการคลังของรัฐของคณะกรรมการตรวจเงินแผ่นดิน และคำพิพากษาศาลปกครองสูงสุดที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('005', 10, 'จัดทำฐานข้อมูลสำนวนความผิดวินัยการเงินการคลังของรัฐ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('005', 11, 'ศึกษา วิเคราะห์ และจัดทำแนวคำวินิจฉัยชี้ขาดของคณะกรรมการตรวจเงินแผ่นดินตลอดจนวิเคราะห์เหตุแห่งคดีที่มีการฟ้องร้องในศาลปกครอง เพื่อเสนอแนะแนวทางการปฏิบัติงานสำนวนความผิดวินัยการเงินการคลังของรัฐให้มีประสิทธิภาพ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('005', 12, 'ศึกษา วิเคราะห์ และรวบรวมข้อมูลทางวิชาการ ข้อกฎหมาย และระเบียบที่เกี่ยวข้อง เพื่อจัดทำคู่มือการปฏิบัติงาน และเพื่อเสนอแนะแนวทางการพัฒนาระบบงานสำนวนความผิดวินัยการเงินการคลังของรัฐ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('005', 13, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('005', 14, 'ปฏิบัติหน้าที่อื่นตามที่คณะกรรมการตรวจเงินแผ่นดิน หรือผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('006', 1, 'ตรวจพิจารณาหรือยกร่างกฎหมาย กฎ ระเบียบ ข้อบังคับ ประกาศ หรือคำสั่ง และตรวจพิจารณาร่างนิติกรรมสัญญาของสำนักงานการตรวจเงินแผ่นดิน ตลอดจนหนังสือแจ้งหน่วยงานที่เกี่ยวข้อง และเสนอความเห็นเพื่อประกอบการพิจารณาสั่งการของคณะกรรมการตรวจเงินแผ่นดิน และผู้ว่าการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('006', 2, 'ศึกษา วิเคราะห์ ปรับปรุง หรือแก้ไขกฎหมายที่เกี่ยวข้องกับการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('006', 3, 'ให้คำปรึกษา แนะนำ ให้ความเห็น ตอบข้อหารือทางด้านกฎหมาย ระเบียบ ประกาศ คำสั่งหรือข้อบังคับที่เกี่ยวกับหน้าที่และอำนาจของคณะกรรมการตรวจเงินแผ่นดิน ผู้ว่าการตรวจเงินแผ่นดิน และสำนักงานการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('006', 4, 'กลั่นกรองและสอบทานรายงานการตรวจสอบของสำนักงานการตรวจเงินแผ่นดินเพื่อวินิจฉัยประเด็นข้อกฎหมายประกอบการพิจารณาของผู้ว่าการตรวจเงินแผ่นดิน หรือผู้ที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('006', 5, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('006', 6, 'ปฏิบัติหน้าที่อื่นตามที่คณะกรรมการตรวจเงินแผ่นดิน หรือผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('007', 1, 'ดำเนินการเกี่ยวกับงานคดีของคณะกรรมการตรวจเงินแผ่นดิน ผู้ว่าการตรวจเงินแผ่นดิน สำนักงานการตรวจเงินแผ่นดิน และคณะอนุกรรมการข้าราชการสำนักงานการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('007', 2, 'จัดหา รวบรวม และจัดระบบศึกษาค้นคว้าเกี่ยวกับคดีแพ่ง คดีอาญา คดีปกครองและคดีรัฐธรรมนูญ ที่เกี่ยวข้องกับการปฏิบัติหน้าที่ของคณะกรรมการตรวจเงินแผ่นดิน ผู้ว่าการตรวจเงินแผ่นดิน และสำนักงานการตรวจเงินแผ่นดิน เพื่อจัดทำฐานข้อมูลสำหรับใช้เป็นแนวทางในการดำเนินคดี และเสนอแนะเกี่ยวกับการปฏิบัติหน้าที่ของคณะกรรมการตรวจเงินแผ่นดิน ผู้ว่าการตรวจเงินแผ่นดิน สำนักงานการตรวจเงินแผ่นดิน และคณะอนุกรรมการข้าราชการสำนักงานการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('007', 3, 'ดำเนินการประสานงานคดีกับบุคคล ส่วนราชการภายในและภายนอก รวมถึงหน่วยงานอื่นซึ่งเกี่ยวข้องในคดี');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('007', 4, 'จัดหา รวบรวม และจัดระบบเพื่อการจัดทำฐานข้อมูลกฎหมาย ระเบียบ ข้อบังคับมติคณะรัฐมนตรี คำสั่ง หรือหนังสือสั่งการของส่วนราชการที่เกี่ยวกับคดีพิพาทสำหรับใช้ศึกษา ค้นคว้า อ้างอิง และเผยแพร่แก่ข้าราชการและลูกจ้างของสำนักงานการตรวจเงินแผ่นดิน รวมทั้งวิเคราะห์เหตุแห่งการกระทำความผิดสำหรับใช้เป็นแนวการตรวจสอบหรือการปฏิบัติงานของสำนักงานการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('007', 5, 'ดำเนินการเกี่ยวกับการใช้มาตรการบังคับทางปกครอง และการบังคับคดี');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('007', 6, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('007', 7, 'ปฏิบัติหน้าที่อื่นตามที่คณะกรรมการตรวจเงินแผ่นดิน หรือผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('008', 1, 'ดำเนินกิจกรรมตามภารกิจภายใต้กรอบความร่วมมือพันธกรณีระหว่างประเทศที่สำนักงานการตรวจเงินแผ่นดินเป็นสมาชิก ศึกษา พัฒนา และแสวงหาความร่วมมือระหว่างประเทศ ศึกษาวิเคราะห์ และรวบรวมองค์ความรู้เกี่ยวกับการตรวจเงินแผ่นดิน หรือที่เป็นประโยชน์ต่อการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('008', 2, 'ประสานงานอำนวยความสะดวกเกี่ยวกับงานพิธีการ รวมทั้งทำหน้าที่ล่ามในการประชุม สัมมนา อบรม ศึกษาดูงาน หรือการเยือนระหว่างประเทศ รวมถึงความสัมพันธ์ระหว่างประเทศ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('008', 3, 'ประสานงานอำนวยความสะดวกเกี่ยวกับงานพิธีการ รวมทั้งทำหน้าที่ล่ามในการต้อนรับ ประชุม สัมมนา อบรม ศึกษาดูงาน แก่บุคคลสำคัญที่มาเยือน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('008', 4, 'จัดทำ รวบรวม ข้อมูลข่าวสาร เอกสารทางวิชาการ ถ่ายทอดหรือเผยแพร่องค์ความรู้ที่ได้จากการประชุม อบรม สัมมนา หรือการศึกษาดูงานต่างประเทศ รวมทั้งเสนอแนะแนวทางที่สามารถนำมาปรับใช้กับการตรวจเงินแผ่นดินให้เป็นรูปธรรม');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('008', 5, 'ให้บริการข้อมูลด้านการต่างประเทศ รวมถึงแปลข้อมูลที่เป็นภาษาต่างประเทศตามที่หน่วยงานภายในร้องขอ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('008', 6, 'ประสานงาน และร่วมมือกับส่วนราชการภายในสำนักงานการตรวจเงินแผ่นดินรวมทั้งหน่วยงานภายในประเทศและต่างประเทศที่เกี่ยวข้องกับการตรวจเงินแผ่นดิน หรือการตรวจสอบระหว่างประเทศ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('008', 7, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('008', 8, 'ปฏิบัติหน้าที่อื่นตามที่คณะกรรมการตรวจเงินแผ่นดิน หรือผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('009', 1, 'ศึกษา วิเคราะห์ และวิจัยเพื่อสร้างองค์ความรู้ที่เป็นประโยชน์ต่อการเพิ่มประสิทธิผล และประสิทธิภาพในงานตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('009', 2, 'พัฒนา และจัดทำแนวปฏิบัติและคู่มือการตรวจสอบภายใต้หลักเกณฑ์มาตรฐานที่เกี่ยวกับการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('009', 3, 'ให้คำปรึกษา แนะนำในด้านวิชาการ แนวปฏิบัติและคู่มือการปฏิบัติงานที่เกี่ยวข้องกับการตรวจสอบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('009', 4, 'ประสานเครือข่ายทางด้านวิชาการ หรือด้านวิจัยเพื่อแลกเปลี่ยนเรียนรู้ และร่วมมือกันในการพัฒนาการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('009', 5, 'พัฒนาต่อยอดองค์ความรู้ที่ได้รับจากการศึกษา วิจัย เพื่อนำมาใช้ประโยชน์ในการสร้างนวัตกรรมการตรวจเงินแผ่นดิน และแก้ไขปัญหาในการตรวจสอบที่เกิดขึ้นได้อย่างเป็นรูปธรรม');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('009', 6, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('009', 7, 'ปฏิบัติหน้าที่อื่นตามที่คณะกรรมการตรวจเงินแผ่นดิน หรือผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('010', 1, 'ศึกษา วิเคราะห์ เสนอแนะ จัดทำร่างนโยบายการตรวจเงินแผ่นดินประจำปี แผนการตรวจสอบประจำปี และแผนการปฏิบัติราชการของสำนักงานการตรวจเงินแผ่นดินให้สอดคล้องกับนโยบายการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('010', 2, 'ศึกษา วิเคราะห์ รวบรวม และจัดทำร่างคำของบประมาณประจำปี');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('010', 3, 'ศึกษา วิเคราะห์ และดำเนินการเพื่อให้สำนักงานการตรวจเงินแผ่นดินมีกระบวนการบริหารความเสี่ยงอย่างเป็นระบบ มีรูปแบบการบริหารจัดการการปฏิบัติงาน และการจัดสรรทรัพยากรอย่างมีประสิทธิภาพ เกิดประสิทธิผล และเป็นไปในทิศทางเดียวกัน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('010', 4, 'ติดตามและประเมินผลการปฏิบัติงานของส่วนราชการภายในตามแผนปฏิบัติราชการประจำปี');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('010', 5, 'จัดทำรายงานผลการปฏิบัติงานประจำปี และรายงานผลการปฏิบัติงานระหว่างปี เสนอต่อคณะกรรมการตรวจเงินแผ่นดินเพื่อให้คำแนะนำ ข้อเสนอแนะ และพิจารณาให้ความเห็นชอบก่อนเสนอสภาผู้แทนราษฎร วุฒิสภา และคณะรัฐมนตรีทราบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('010', 6, 'ติดตาม รวบรวม และเผยแพร่ผลการดำเนินการของหน่วยรับตรวจตามข้อเสนอแนะของสำนักงานการตรวจเงินแผ่นดิน แล้วเสนอผู้ว่าการตรวจเงินแผ่นดิน และคณะกรรมการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('010', 7, 'ศึกษา วิเคราะห์ พัฒนาระบบ และกำหนดรูปแบบมาตรฐานและวิธีการในการติดตามและประเมินผล');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('010', 8, 'ดำเนินการให้มีการประเมินผลการปฏิบัติงานของสำนักงานการตรวจเงินแผ่นดินโดยผู้ประเมินอิสระ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('010', 9, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('010', 10, 'ปฏิบัติหน้าที่อื่นตามที่คณะกรรมการตรวจเงินแผ่นดิน หรือผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('011', 1, 'เผยแพร่ประชาสัมพันธ์ข้อมูลข่าวสารของคณะกรรมการตรวจเงินแผ่นดิน ผู้ว่าการตรวจเงินแผ่นดิน และสำนักงานการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('011', 2, 'ดำเนินการด้านการประชาสัมพันธ์เพื่อให้เกิดความโปร่งใสสามารถตรวจสอบได้ เกิดภาพลักษณ์ที่ดี และมีความเชื่อมั่นต่อสำนักงานการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('011', 3, 'จัดทำและประสานแผนงาน รวมทั้งติดตาม เร่งรัด และประเมินผลงานการประชาสัมพันธ์ของสำนักงานการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('011', 4, 'ผลิตสื่อประชาสัมพันธ์และโสตทัศนูปกรณ์ สื่อมัลติมีเดีย และการผลิตสื่อในรูปแบบและลักษณะต่าง ๆ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('011', 5, 'รวบรวม ศึกษา วิเคราะห์ วิจัย และประเมินคุณค่าความสำคัญของเอกสารจัดหมวดหมู่ อนุรักษ์ เผยแพร่ และให้บริการ เอกสารจดหมายเหตุของคณะกรรมการตรวจเงินแผ่นดิน ผู้ว่าการตรวจเงินแผ่นดิน และสำนักงานการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('011', 6, 'ประสานความร่วมมือด้านประชาสัมพันธ์กับหน่วยงานภาครัฐ ภาคประชาชน และสื่อมวลชน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('011', 7, 'สนับสนุนการปฏิบัติหน้าที่ของโฆษกคณะกรรมการตรวจเงินแผ่นดินและสำนักงานการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('011', 8, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('011', 9, 'ปฏิบัติหน้าที่อื่นตามที่คณะกรรมการตรวจเงินแผ่นดิน หรือผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('012', 1, 'ดำเนินการเกี่ยวกับการบริหารจัดการ การเงินและทรัพย์สิน การงบประมาณของสำนักงานการตรวจเงินแผ่นดิน รวมทั้งจัดทำแผนการใช้จ่ายเงินประจำปี ควบคุม ติดตาม เร่งรัด และรายงานผลการใช้จ่ายเงินงบประมาณ และเงินกองทุนเพื่อการพัฒนาการตรวจเงินแผ่นดินเพื่อให้เป็นไปตามกฎหมาย ระเบียบ ข้อบังคับ หรือมติที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('012', 2, 'ดำเนินการเกี่ยวกับการจัดทำบัญชี และรายงานการเงินประจำปีงบประมาณของสำนักงานการตรวจเงินแผ่นดิน และการนำส่ง ให้เป็นไปตามกฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('012', 3, 'จัดทำแนวทาง และวิธีปฏิบัติเกี่ยวกับการรับ การจ่าย การเก็บรักษา และการนำส่งเงินของสำนักงานการตรวจเงินแผ่นดิน ให้สอดคล้องกับหลักการนโยบายของการบัญชีภาครัฐ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('012', 4, 'ปฏิบัติงานธุรการ งานอำนวยการ งานเลขานุการ และงานการประชุม ของคณะกรรมการกองทุนเพื่อการพัฒนาการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('012', 5, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('012', 6, 'ปฏิบัติหน้าที่อื่นตามที่คณะกรรมการตรวจเงินแผ่นดิน หรือผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('013', 1, 'ปฏิบัติงานสารบรรณ งานอำนวยการ และงานประสานราชการของสำนักงานการตรวจเงินแผ่นดิน รวมทั้งเป็นหน่วยงานธุรการกลางในการติดต่อราชการทั้งภายในและภายนอกสำนักงานการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('013', 2, 'ดำเนินการเกี่ยวกับการบริหารพัสดุ การจัดหา การบริการ การควบคุม ดูแล บำรุงรักษาเกี่ยวกับยานพาหนะ อาคารสถานที่และอุปกรณ์ และงานด้านการพิมพ์ รวมทั้งการรักษาความปลอดภัยของสำนักงานการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('013', 3, 'ดำเนินการเกี่ยวกับการเปิดเผย และการให้บริการข้อมูลข่าวสารทางราชการของสำนักงานการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('013', 4, 'ดำเนินการเกี่ยวกับงานวิศวกรรม การออกแบบ ตรวจแบบรูปรายการงานก่อสร้าง การคำนวณราคากลาง และการดำเนินการอื่นในส่วนที่เกี่ยวข้องกับงานจ้างก่อสร้างของสำนักงานการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('013', 5, 'ดำเนินการเกี่ยวกับราชการทั่วไปและราชการที่มิได้กำหนดให้เป็นหน้าที่ของส่วนราชการใดของสำนักงานการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('013', 6, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('013', 7, 'ปฏิบัติหน้าที่อื่นตามที่คณะกรรมการตรวจเงินแผ่นดิน หรือผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('014', 1, 'จัดทำแผนการบริหารทรัพยากรบุคคลของสำนักงานการตรวจเงินแผ่นดินตามนโยบายการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('014', 2, 'ดำเนินการเกี่ยวกับการแบ่งส่วนราชการภายใน ขอบเขตหน้าที่และอำนาจของส่วนราชการ และการจัดอัตรากำลังของสำนักงานการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('014', 3, 'ดำเนินการเกี่ยวกับการกำหนดตำแหน่ง การจัดประเภทตำแหน่งและระดับตำแหน่ง และการเทียบตำแหน่ง อัตราเงินเดือน เงินเพิ่มพิเศษสำหรับตำแหน่ง ค่าตอบแทนพิเศษ หรือสิทธิประโยชน์อื่นของเจ้าหน้าที่');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('014', 4, 'ดำเนินการเกี่ยวกับการกำหนดคุณสมบัติ การคัดเลือก การบรรจุ การแต่งตั้งการออกจากราชการ วินัย การอุทธรณ์ และการร้องทุกข์ สำหรับเจ้าหน้าที่');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('014', 5, 'พัฒนาระบบข้อมูลสารสนเทศด้านบุคลากร และทะเบียนประวัติบุคลากรของสำนักงานการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('014', 6, 'กำหนดวิธีการ และเงื่อนไขในการจ้างลูกจ้างของสำนักงานการตรวจเงินแผ่นดิน รวมทั้งอัตราเงินเดือน เงินเพิ่ม และค่าตอบแทนพิเศษ หรือสิทธิประโยชน์อื่นของลูกจ้างดังกล่าว');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('014', 7, 'ดำเนินการเกี่ยวกับงานสวัสดิการ หรือการสงเคราะห์อื่นแก่เจ้าหน้าที่ และบุคลากรอื่นของสำนักงานการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('014', 8, 'ดำเนินการเกี่ยวกับการบริหารงานบุคคล การเสริมสร้างวินัย และรักษาระบบคุณธรรม จริยธรรม จรรยาบรรณ ของข้าราชการและลูกจ้างสำนักงานการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('014', 9, 'ปฏิบัติงานธุรการ งานอำนวยการ งานเลขานุการ และงานการประชุมของคณะกรรมการตรวจเงินแผ่นดินในฐานะองค์กรกลางบริหารงานบุคคล คณะอนุกรรมการข้าราชการสำนักงานการตรวจเงินแผ่นดิน และคณะกรรมการมาตรฐานทางจริยธรรมของเจ้าหน้าที่และบุคลากรอื่นของสำนักงานการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('014', 10, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('014', 11, 'ปฏิบัติหน้าที่อื่นตามที่คณะกรรมการตรวจเงินแผ่นดิน หรือผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('015', 1, 'กำหนดเป้าหมาย ทิศทาง ภารกิจงานตรวจสอบภายในเพื่อสนับสนุนการบริหารงานและการดำเนินงานด้านต่าง ๆ ของสำนักงานการตรวจเงินแผ่นดิน ให้สอดคล้องกับนโยบายของสำนักงานการตรวจเงินแผ่นดิน คณะกรรมการตรวจเงินแผ่นดิน และคณะกรรมการตรวจสอบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('015', 2, 'กำหนดกฎบัตรไว้เป็นลายลักษณ์อักษร เสนอผู้ว่าการตรวจเงินแผ่นดิน ก่อนเสนอคณะกรรมการตรวจสอบเพื่อพิจารณาให้ความเห็นชอบ และเผยแพร่ให้ส่วนราชการภายในของสำนักงานการตรวจเงินแผ่นดินทราบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('015', 3, 'จัดให้มีการประกันและปรับปรุงคุณภาพงานตรวจสอบภายใน ทั้งภายในและภายนอกตามรูปแบบและวิธีการที่กรมบัญชีกลางกำหนด');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('015', 4, 'จัดทำและเสนอแผนการตรวจสอบภายในประจำปีต่อผู้ว่าการตรวจเงินแผ่นดิน ก่อนเสนอคณะกรรมการตรวจสอบ เพื่อพิจารณาอนุมัติ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('015', 5, 'ปฏิบัติงานตรวจสอบให้เป็นไปตามแผนการตรวจสอบภายในประจำปีที่ได้รับอนุมัติและสรุปผลการตรวจสอบการปฏิบัติงานตามแผนการตรวจสอบประจำปีรายงานต่อผู้ว่าการตรวจเงินแผ่นดิน คณะกรรมการตรวจสอบ และคณะกรรมการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('015', 6, 'จัดทำและเสนอรายงานผลการตรวจสอบต่อผู้ว่าการตรวจเงินแผ่นดิน และคณะกรรมการตรวจสอบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('015', 7, 'ติดตามผลการตรวจสอบ เสนอแนะ และให้คำปรึกษาแก่ส่วนราชการภายในของสำนักงานการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('015', 8, 'จัดทำรายงานผลการดำเนินงานของคณะกรรมการตรวจสอบ เสนอคณะกรรมการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('015', 9, 'ปฏิบัติงานอื่นที่เกี่ยวข้องกับการตรวจสอบภายในตามหลักเกณฑ์ที่กระทรวงการคลังกำหนด');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('015', 10, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('015', 11, 'ปฏิบัติหน้าที่อื่นตามที่คณะกรรมการตรวจเงินแผ่นดิน หรือผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('016', 1, 'จัดทำนโยบายการประกันคุณภาพ และหลักเกณฑ์การสอบทานเพื่อการประกันคุณภาพ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('016', 2, 'ติดตามและประเมินผลการควบคุมคุณภาพ และการปฏิบัติตามมาตรฐาน แนวปฏิบัติ หรือคู่มือการตรวจสอบ รวมทั้งจัดทำรายงานการประกันคุณภาพระดับงานตรวจสอบ และระดับองค์กรพร้อมข้อเสนอแนะในการปรับปรุงจุดอ่อนหรือข้อบกพร่องในการปฏิบัติงาน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('016', 3, 'เสนอความเห็นต่อผู้ว่าการตรวจเงินแผ่นดินเพื่อพิจารณาให้ความเห็นชอบผู้สอบบัญชีตามระเบียบที่คณะกรรมการตรวจเงินแผ่นดินกำหนด รวมถึงระเบียบ ประกาศ และคำสั่งที่ผู้ว่าการตรวจเงินแผ่นดินกำหนด');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('016', 4, 'พิจารณาแจ้งผลการตรวจสอบไปยังหน่วยรับตรวจกรณีการตรวจสอบรายงานการเงินหรือการตรวจสอบอื่นโดยผู้สอบบัญชีที่สำนักงานการตรวจเงินแผ่นดินให้ความเห็นชอบตามระเบียบ ประกาศ และคำสั่งที่ผู้ว่าการตรวจเงินแผ่นดินกำหนด');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('016', 5, 'กำกับดูแลผู้สอบบัญชีที่สำนักงานการตรวจเงินแผ่นดินให้ความเห็นชอบปฏิบัติงานให้เป็นไปตามนโยบายการตรวจเงินแผ่นดิน หลักเกณฑ์มาตรฐานที่เกี่ยวกับการตรวจเงินแผ่นดินและมาตรฐานวิชาชีพ รวมถึงการติดตาม และการพิจารณาเรื่องร้องเรียนที่เกี่ยวกับผู้สอบบัญชีที่สำนักงานการตรวจเงินแผ่นดินให้ความเห็นชอบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('016', 6, 'ให้คำปรึกษา แนะนำ และความเห็นแก่ผู้สอบบัญชี และบุคลากรของสำนักงานการตรวจเงินแผ่นดิน ในการปฏิบัติให้ถูกต้องตามระเบียบ ประกาศ มาตรฐาน หลักเกณฑ์ คำสั่ง แนวปฏิบัติ และคู่มือการปฏิบัติงานที่เกี่ยวข้องกับผู้สอบบัญชี');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('016', 7, 'จัดทำทะเบียนผู้สอบบัญชีที่สำนักงานการตรวจเงินแผ่นดินให้ความเห็นชอบและข้อมูลอื่นที่เกี่ยวกับผู้สอบบัญชีที่สำนักงานการตรวจเงินแผ่นดินให้ความเห็นชอบ เพื่อเผยแพร่หรือให้ผู้สอบบัญชี บุคลากรของสำนักงานการตรวจเงินแผ่นดิน และผู้เกี่ยวข้องนำไปใช้ประโยชน์ตามความเหมาะสม');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('016', 8, 'ศึกษา และวิเคราะห์เพื่อให้ความเห็น และเสนอแนะในการพัฒนาหรือปรับปรุงระเบียบ ประกาศ มาตรฐาน หลักเกณฑ์ คำสั่ง แนวปฏิบัติ และคู่มือการปฏิบัติงาน ที่เกี่ยวข้องกับผู้สอบบัญชีที่สำนักงานการตรวจเงินแผ่นดินให้ความเห็นชอบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('016', 9, 'รวบรวมข้อสังเกตหรือคำสั่งของผู้ว่าการตรวจเงินแผ่นดิน และเจ้าหน้าที่ที่มีถึงหน่วยรับตรวจในส่วนที่เกี่ยวกับผลการตรวจสอบ เพื่อเสนอคณะกรรมการตรวจเงินแผ่นดินพิจารณาวางหลักเกณฑ์ให้เจ้าหน้าที่ปฏิบัติให้เป็นมาตรฐาน รวมถึงเผยแพร่ให้หน่วยรับตรวจและประชาชนทราบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('016', 10, 'ส่งเสริม สนับสนุน และให้คำปรึกษา แนะนำ เกี่ยวกับการควบคุมคุณภาพ และการประกันคุณภาพ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('016', 11, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('016', 12, 'ปฏิบัติหน้าที่อื่นตามที่คณะกรรมการตรวจเงินแผ่นดิน หรือผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('017', 1, 'จัดทำแผนพัฒนาศักยภาพบุคลากรของสำนักงานการตรวจเงินแผ่นดินรวมถึงบุคลากรภาครัฐและภาคส่วนต่าง ๆ และแผนการดำเนินงานอื่นของสถาบันพัฒนาการตรวจเงินแผ่นดินให้สอดคล้องตามนโยบายการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('017', 2, 'จัดทำและพัฒนาหลักสูตรพื้นฐาน หลักสูตรเฉพาะด้าน เพื่อพัฒนาวิชาชีพด้านการตรวจเงินแผ่นดินทั้งภาคทฤษฎี และภาคปฏิบัติอย่างเป็นระบบ และหลักสูตรที่เกี่ยวกับการเสริมสร้างการบริหารการเงินการคลังของรัฐ สำหรับบุคลากรของสำนักงานการตรวจเงินแผ่นดิน บุคลากรภาครัฐและภาคส่วนต่าง ๆ รวมถึงองค์กรเครือข่ายการตรวจสอบระหว่างประเทศ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('017', 3, 'จัดการฝึกอบรม ส่งเสริม และพัฒนาการเรียนรู้สรรพวิทยาการด้านการตรวจเงินแผ่นดิน และการรักษาวินัยการเงินการคลังของรัฐ เพื่อพัฒนาองค์ความรู้และศักยภาพให้กับบุคลากรของสำนักงานการตรวจเงินแผ่นดิน รวมทั้งบุคลากรหน่วยงานภาครัฐ และภาคส่วนต่างๆ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('017', 4, 'ดำเนินการเกี่ยวกับการเสริมสร้างบุคลากรของสำนักงานการตรวจเงินแผ่นดินในการปฏิบัติตนให้เป็นไปตามกฎหมายและมาตรฐานทางจริยธรรม');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('017', 5, 'ศึกษา และพัฒนานวัตกรรม เพื่อเพิ่มประสิทธิภาพงานด้านการพัฒนาบุคลากรของสำนักงานการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('017', 6, 'การบริหารจัดการความรู้ โดยร่วมมือกับหน่วยงานทั้งภายในและต่างประเทศหรือหน่วยงานระหว่างประเทศ เพื่อแลกเปลี่ยนองค์ความรู้ และประสบการณ์ด้านการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('017', 7, 'ติดตามประเมินผลการพัฒนาบุคลากรของสำนักงานการตรวจเงินแผ่นดิน เพื่อเสนอแนวทางการพัฒนาและแก้ไขปัญหา');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('017', 8, 'พัฒนาระบบฐานข้อมูลการพัฒนาบุคลากรของสำนักงานการตรวจเงินแผ่นดินเพื่อนำมาใช้ในการวางแผนการพัฒนาบุคลากรอย่างเป็นระบบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('017', 9, 'ให้บริการและอำนวยความสะดวกในการใช้เทคโนโลยีและโสตทัศนูปกรณ์ แก่บุคลากรของสำนักงานการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('017', 10, 'ให้บริการห้องสมุด บริการอ้างอิงระหว่างห้องสมุด และดำเนินการเกี่ยวกับห้องสมุดอิเล็กทรอนิกส์ ตลอดจนพัฒนาการบริหารจัดการห้องสมุด เพื่อให้ห้องสมุดมีแหล่งข้อมูลที่ทันสมัย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('017', 11, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('017', 12, 'ปฏิบัติหน้าที่อื่นตามที่คณะกรรมการตรวจเงินแผ่นดิน หรือผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('018', 1, 'ศึกษา วิเคราะห์ เพื่อเสนอนโยบาย และจัดทำแผนปฏิบัติการดิจิทัลเพื่อการตรวจเงินแผ่นดิน และการบริหารจัดการสำนักงานการตรวจเงินแผ่นดิน รวมทั้งการบูรณาการเกี่ยวกับระบบดิจิทัลเพื่อการตรวจเงินแผ่นดินให้เป็นไปตามมาตรฐานและมาตรการทางดิจิทัลที่กฎหมายกำหนด');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('018', 2, 'พัฒนาระบบดิจิทัล และโครงสร้างพื้นฐานดิจิทัล สร้างนวัตกรรม นำระบบปัญญาประดิษฐ์ หรือระบบอื่นในลักษณะเดียวกันมาใช้ในการตรวจสอบ กำหนดมาตรฐานข้อมูล การเชื่อมโยงข้อมูล การรักษาความมั่นคงปลอดภัยในการใช้ระบบดิจิทัล การสื่อสารและนำเสนอข้อมูลโดยใช้ดิจิทัลเพื่อสนับสนุนการปฏิบัติงานด้านการตรวจสอบ และสนับสนุนการปฏิบัติงานของสำนักงานการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('018', 3, 'บริหารจัดการข้อมูลและคลังข้อมูล และการเชื่อมโยงข้อมูลภายในและภายนอกหน่วยงาน ให้เป็นไปตามหลักธรรมาภิบาลข้อมูล');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('018', 4, 'ส่งเสริมการใช้เทคโนโลยีดิจิทัลเพื่อการตรวจเงินแผ่นดิน และบริหารจัดการ กำกับดูแล การใช้งาน การบำรุงรักษา โครงสร้างพื้นฐาน ระบบดิจิทัล ให้เพียงพอและมีประสิทธิภาพ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('018', 5, 'ส่งเสริมการมีส่วนร่วมในการตรวจเงินแผ่นดิน แก่ผู้มีส่วนได้เสียและประชาชนอย่างทั่วถึง รวดเร็วและโปร่งใสตามหลักธรรมาภิบาลโดยใช้ระบบดิจิทัล');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('018', 6, 'กำหนดแนวทางพัฒนาบุคลากรด้านดิจิทัล บุคลากรด้านการตรวจสอบและบุคลากรด้านสนับสนุน ให้มีความรู้ ความสามารถ และความเชี่ยวชาญด้านดิจิทัลให้เกิดประโยชน์ต่อการตรวจเงินแผ่นดินและการบริหารจัดการสำนักงานการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('018', 7, 'จัดทำมาตรฐาน หรือมาตรการ หรือกรอบแนวทางปฏิบัติ หรือการกำหนดในลักษณะอื่นเกี่ยวกับการนำดิจิทัลมาใช้ในการตรวจสอบและการปฏิบัติราชการให้สำนักงานการตรวจเงินแผ่นดิน หน่วยรับตรวจ และหน่วยงานที่เกี่ยวข้องให้มีการปฏิบัติราชการที่มีประสิทธิภาพ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('018', 8, 'สนับสนุนการปฏิบัติราชการทางอิเล็กทรอนิกส์ในการตรวจเงินแผ่นดินและการปฏิบัติงานของสำนักงานการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('018', 9, 'ติดตาม ประเมิน และรายงานผล เกี่ยวกับระบบดิจิทัล และการบริหารจัดการเพื่อพัฒนาและปรับปรุงการปฏิบัติงานของสำนักงานการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('018', 10, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('018', 11, 'ปฏิบัติหน้าที่อื่นตามที่คณะกรรมการตรวจเงินแผ่นดิน หรือผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('019', 1, 'ตรวจเงินแผ่นดินตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย ให้เป็นไปตามนโยบายการตรวจเงินแผ่นดิน หลักเกณฑ์มาตรฐานที่เกี่ยวกับการตรวจเงินแผ่นดิน กฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน กฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ และกฎหมายที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('019', 2, 'ตรวจสอบทางบัญชีนิติวิทยา (Forensic Accounting) เพื่อสนับสนุนการได้มาซึ่งหลักฐานการตรวจสอบที่เพียงพอในการแสดงความเห็นของผู้ตรวจสอบตามหลักเกณฑ์มาตรฐานที่คณะกรรมการตรวจเงินแผ่นดินกำหนด');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('019', 3, 'ตรวจสอบระบบสารสนเทศของหน่วยรับตรวจให้มีการควบคุมที่เพียงพอและมีประสิทธิผลเป็นไปตามกฎหมาย ระเบียบ ข้อบังคับ มาตรฐานการควบคุมเทคโนโลยีสารสนเทศ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('019', 4, 'ตรวจสอบระบบสารสนเทศและข้อมูลสารสนเทศของหน่วยรับตรวจว่ามีการปฏิบัติราชการเป็นไปตามกฎหมาย ระเบียบ ข้อบังคับ และแผนพัฒนาประเทศ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('019', 5, 'ศึกษา วิจัย และพัฒนางานเทคโนโลยีสารสนเทศ เพื่อสนับสนุนงานตรวจสอบและประเมินความเสี่ยงของระบบงานคอมพิวเตอร์ของหน่วยรับตรวจ เพื่อให้ผู้ตรวจสอบสามารถวางแผนการตรวจสอบได้อย่างเหมาะสม');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('019', 6, 'ให้ความร่วมมือในการพิจารณาขอบเขตการตรวจสอบ แผนการตรวจสอบและการดำเนินการตรวจสอบระบบสารสนเทศ สำหรับวงจรธุรกิจหรือระบบสำคัญของหน่วยรับตรวจที่ดำเนินการภายใต้สภาพแวดล้อมของระบบสารสนเทศที่ใช้คอมพิวเตอร์');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('019', 7, 'นำเสนอประเด็นและข้อมูลเกี่ยวกับการจัดทำผลผลิตของงานที่เสริมสร้างความเข้มแข็งให้กับงานตรวจสอบ (Non – Audit Product) ต่อผู้ว่าการตรวจเงินแผ่นดินเพื่อเสนอต่อคณะกรรมการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('019', 8, 'แจ้งผลการตรวจสอบและติดตามให้หน่วยงานที่เกี่ยวข้องดำเนินการตามหน้าที่และอำนาจเพื่อให้เป็นไปตามผลการตรวจสอบ ตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('019', 9, 'ติดตามผลการดำเนินงานของหน่วยรับตรวจตามข้อตรวจพบ ข้อสังเกตและข้อเสนอแนะของสำนักงานการตรวจเงินแผ่นดิน ตามหลักเกณฑ์ที่ผู้ว่าการตรวจเงินแผ่นดินกำหนด');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('019', 10, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('019', 11, 'ปฏิบัติหน้าที่อื่นตามที่คณะกรรมการตรวจเงินแผ่นดิน หรือผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('020', 1, 'ตรวจเงินแผ่นดินตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย ให้เป็นไปตามนโยบายการตรวจเงินแผ่นดิน หลักเกณฑ์มาตรฐานที่เกี่ยวกับการตรวจเงินแผ่นดิน กฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน กฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ และกฎหมายที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('020', 2, 'ตรวจสอบการปฏิบัติตามกฎหมาย เกี่ยวกับการจัดซื้อจัดจ้างโครงการขนาดใหญ่ที่มีมูลค่าเกินกว่าหนึ่งพันล้านบาทและโครงการร่วมลงทุน (PPP) และตรวจสอบผลสัมฤทธิ์และประสิทธิภาพของการจัดซื้อจัดจ้าง [Procurement Performance Audit (PPA)]');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('020', 3, 'สนับสนุนการตรวจสอบการจัดซื้อจัดจ้างของสำนักตรวจสอบอื่น ๆ ทั้งส่วนกลาง หรือส่วนภูมิภาค ตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('020', 4, 'เสนอความเห็นเพื่อแก้ไข ปรับปรุงระเบียบ ข้อบังคับ ประกาศ คู่มือ หรืออื่น ๆ เพื่อใช้ในการตรวจสอบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('020', 5, 'นำเสนอประเด็นและข้อมูลเกี่ยวกับการจัดทำผลผลิตของงานที่เสริมสร้างความเข้มแข็งให้กับงานตรวจสอบ (Non – Audit Product) ต่อผู้ว่าการตรวจเงินแผ่นดินเพื่อเสนอต่อคณะกรรมการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('020', 6, 'แจ้งผลการตรวจสอบและติดตามให้หน่วยงานที่เกี่ยวข้องดำเนินการตามหน้าที่และอำนาจเพื่อให้เป็นไปตามผลการตรวจสอบ ตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('020', 7, 'ติดตามผลการดำเนินงานของหน่วยรับตรวจตามข้อตรวจพบ ข้อสังเกตและข้อเสนอแนะของสำนักงานการตรวจเงินแผ่นดิน ตามหลักเกณฑ์ที่ผู้ว่าการตรวจเงินแผ่นดินกำหนด');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('020', 8, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('020', 9, 'ปฏิบัติหน้าที่อื่นตามที่คณะกรรมการตรวจเงินแผ่นดิน หรือผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('021', 1, 'ตรวจเงินแผ่นดินตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย ให้เป็นไปตามนโยบายการตรวจเงินแผ่นดิน หลักเกณฑ์มาตรฐานที่เกี่ยวกับการตรวจเงินแผ่นดิน กฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน กฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ และกฎหมายที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('021', 2, 'ตรวจสอบรายงานการเงินและที่หน่วยงานของรัฐส่งให้ตามกฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('021', 3, 'ตรวจสอบรายงานการเงินแผ่นดินประจำปีงบประมาณ และแสดงความเห็นว่าเป็นไปตามกฎหมายและตามความเป็นจริงหรือไม่');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('021', 4, 'ตรวจสอบบัญชีทุนสำรองเงินตราประจำปี และแสดงความเห็นว่าเป็นไปตามกฎหมายและตามความเป็นจริงหรือไม่');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('021', 5, 'ตรวจสอบการใช้จ่ายเงินราชการลับ หรือเงินที่มีลักษณะคล้ายกับเงินราชการลับให้เป็นไปตามหลักเกณฑ์ที่คณะกรรมการตรวจเงินแผ่นดินกำหนด');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('021', 6, 'ตรวจสอบเงินอุดหนุนของหน่วยรับตรวจที่ได้รับเงินอุดหนุน หรือกิจการที่ได้รับเงิน หรือทรัพย์สินลงทุนจากหน่วยงานของรัฐ รัฐวิสาหกิจ หรือหน่วยงานอื่นของรัฐ ว่ามีการใช้จ่ายเป็นไปตามวัตถุประสงค์หรือไม่');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('021', 7, 'ตรวจสอบการปฏิบัติตามกฎหมาย ตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('021', 8, 'ตรวจสอบผลสัมฤทธิ์และประสิทธิภาพในการใช้จ่ายเงิน และทรัพย์สินอื่นของหน่วยรับตรวจหรือที่อยู่ในความรับผิดชอบของหน่วยรับตรวจ ตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('021', 9, 'ตรวจสอบกรณีผลการตรวจสอบตามหน้าที่และอำนาจ พบข้อบกพร่องว่าหน่วยรับตรวจไม่ปฏิบัติตามกฎหมาย ระเบียบ ข้อบังคับ มติคณะรัฐมนตรี แบบแผนการปฏิบัติราชการและสัญญา');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('021', 10, 'นำเสนอประเด็นและข้อมูลเกี่ยวกับการจัดทำผลผลิตของงานที่เสริมสร้างความเข้มแข็งให้กับงานตรวจสอบ (Non – Audit Product) ต่อผู้ว่าการตรวจเงินแผ่นดินเพื่อเสนอต่อคณะกรรมการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('021', 11, 'แจ้งผลการตรวจสอบและติดตามให้หน่วยงานที่เกี่ยวข้องดำเนินการตามหน้าที่และอำนาจเพื่อให้เป็นไปตามผลการตรวจสอบ ตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('021', 12, 'ติดตามผลการดำเนินงานของหน่วยรับตรวจตามข้อตรวจพบ ข้อสังเกตและข้อเสนอแนะของสำนักงานการตรวจเงินแผ่นดิน ตามหลักเกณฑ์ที่ผู้ว่าการตรวจเงินแผ่นดินกำหนด');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('021', 13, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('021', 14, 'ปฏิบัติหน้าที่อื่นตามที่คณะกรรมการตรวจเงินแผ่นดิน หรือผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('022', 1, 'ตรวจเงินแผ่นดินตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย ให้เป็นไปตามนโยบายการตรวจเงินแผ่นดิน หลักเกณฑ์มาตรฐานที่เกี่ยวกับการตรวจเงินแผ่นดิน กฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน กฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ และกฎหมายที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('022', 2, 'ตรวจสอบรายงานการเงินและที่หน่วยงานของรัฐส่งให้ตามกฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('022', 3, 'ตรวจสอบรายงานการเงินแผ่นดินประจำปีงบประมาณ และแสดงความเห็นว่าเป็นไปตามกฎหมายและตามความเป็นจริงหรือไม่');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('022', 4, 'ตรวจสอบบัญชีทุนสำรองเงินตราประจำปี และแสดงความเห็นว่าเป็นไปตามกฎหมายและตามความเป็นจริงหรือไม่');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('022', 5, 'ตรวจสอบการใช้จ่ายเงินราชการลับ หรือเงินที่มีลักษณะคล้ายกับเงินราชการลับให้เป็นไปตามหลักเกณฑ์ที่คณะกรรมการตรวจเงินแผ่นดินกำหนด');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('022', 6, 'ตรวจสอบเงินอุดหนุนของหน่วยรับตรวจที่ได้รับเงินอุดหนุน หรือกิจการที่ได้รับเงิน หรือทรัพย์สินลงทุนจากหน่วยงานของรัฐ รัฐวิสาหกิจ หรือหน่วยงานอื่นของรัฐ ว่ามีการใช้จ่ายเป็นไปตามวัตถุประสงค์หรือไม่');
