INSERT INTO mandates (dept_id, item_order, content) VALUES ('028', 1, 'ตรวจเงินแผ่นดินตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย ให้เป็นไปตามนโยบายการตรวจเงินแผ่นดิน หลักเกณฑ์มาตรฐานที่เกี่ยวกับการตรวจเงินแผ่นดิน กฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน กฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ และกฎหมายที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('028', 2, 'ตรวจสอบรายงานการเงินและที่หน่วยงานของรัฐส่งให้ตามกฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('028', 3, 'ตรวจสอบรายงานการเงินแผ่นดินประจำปีงบประมาณ และแสดงความเห็นว่าเป็นไปตามกฎหมายและตามความเป็นจริงหรือไม่');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('028', 4, 'ตรวจสอบบัญชีทุนสำรองเงินตราประจำปี และแสดงความเห็นว่าเป็นไปตามกฎหมายและตามความเป็นจริงหรือไม่');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('028', 5, 'ตรวจสอบการใช้จ่ายเงินราชการลับ หรือเงินที่มีลักษณะคล้ายกับเงินราชการลับให้เป็นไปตามหลักเกณฑ์ที่คณะกรรมการตรวจเงินแผ่นดินกำหนด');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('028', 6, 'ตรวจสอบเงินอุดหนุนของหน่วยรับตรวจที่ได้รับเงินอุดหนุน หรือกิจการที่ได้รับเงิน หรือทรัพย์สินลงทุนจากหน่วยงานของรัฐ รัฐวิสาหกิจ หรือหน่วยงานอื่นของรัฐ ว่ามีการใช้จ่ายเป็นไปตามวัตถุประสงค์หรือไม่');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('028', 7, 'ตรวจสอบการปฏิบัติตามกฎหมาย ตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('028', 8, 'ตรวจสอบผลสัมฤทธิ์และประสิทธิภาพในการใช้จ่ายเงิน และทรัพย์สินอื่นของหน่วยรับตรวจหรือที่อยู่ในความรับผิดชอบของหน่วยรับตรวจ ตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('028', 9, 'ตรวจสอบกรณีผลการตรวจสอบตามหน้าที่และอำนาจ พบข้อบกพร่องว่าหน่วยรับตรวจไม่ปฏิบัติตามกฎหมาย ระเบียบ ข้อบังคับ มติคณะรัฐมนตรี แบบแผนการปฏิบัติราชการและสัญญา');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('028', 10, 'นำเสนอประเด็นและข้อมูลเกี่ยวกับการจัดทำผลผลิตของงานที่เสริมสร้างความเข้มแข็งให้กับงานตรวจสอบ (Non – Audit Product) ต่อผู้ว่าการตรวจเงินแผ่นดินเพื่อเสนอต่อคณะกรรมการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('028', 11, 'แจ้งผลการตรวจสอบและติดตามให้หน่วยงานที่เกี่ยวข้องดำเนินการตามหน้าที่และอำนาจเพื่อให้เป็นไปตามผลการตรวจสอบ ตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('028', 12, 'ติดตามผลการดำเนินงานของหน่วยรับตรวจตามข้อตรวจพบ ข้อสังเกตและข้อเสนอแนะของสำนักงานการตรวจเงินแผ่นดิน ตามหลักเกณฑ์ที่ผู้ว่าการตรวจเงินแผ่นดินกำหนด');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('028', 13, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
