INSERT INTO mandates (dept_id, item_order, content) VALUES ('042', 12, 'ติดตามผลการดำเนินงานของหน่วยรับตรวจตามข้อตรวจพบ ข้อสังเกตและข้อเสนอแนะของสำนักงานการตรวจเงินแผ่นดิน ตามหลักเกณฑ์ที่ผู้ว่าการตรวจเงินแผ่นดินกำหนด');
