INSERT INTO mandates (dept_id, item_order, content) VALUES ('044', 1, 'ตรวจเงินแผ่นดินตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย ให้เป็นไปตามนโยบายการตรวจเงินแผ่นดิน หลักเกณฑ์มาตรฐานที่เกี่ยวกับการตรวจเงินแผ่นดิน กฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน กฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ และกฎหมายที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('044', 2, 'ตรวจสอบการจัดเก็บรายได้ การรับ การใช้จ่าย การใช้ประโยชน์ การเก็บรักษา และการบริหารซึ่งเงิน ทรัพย์สิน สิทธิ และผลประโยชน์ของหน่วยรับตรวจหรือที่อยู่ในความครอบครองหรืออำนาจใช้จ่ายของหน่วยรับตรวจรวมถึงการตรวจสอบอื่นตามกฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน และกฎหมายอื่นที่เกี่ยวข้องว่าเป็นไปตามกฎหมาย ระเบียบ ข้อบังคับ มติคณะรัฐมนตรี แบบแผนการปฏิบัติราชการและสัญญา');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('044', 3, 'ตรวจสอบการใช้จ่ายเงินแผ่นดินในกรณีที่มีหลักฐานอันควรเชื่อได้ว่าการใช้จ่ายเงินแผ่นดินมีพฤติการณ์อันเป็นการทุจริตต่อหน้าที่ จงใจปฏิบัติหน้าที่ หรือใช้อำนาจขัดต่อบทบัญญัติแห่งรัฐธรรมนูญหรือกฎหมายหรืออาจทำให้การเลือกตั้งมิได้เป็นไปโดยสุจริตหรือเที่ยงธรรมและเป็นกรณีที่ผู้ว่าการไม่มีอำนาจดำเนินการเพื่อแจ้งหน่วยงานที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('044', 4, 'ตรวจสอบว่าเจ้าหน้าที่ของสำนักงานคณะกรรมการป้องกันและปราบปรามการทุจริตแห่งชาติมีพฤติการณ์อันเป็นการทุจริตต่อหน้าที่ จงใจปฏิบัติหน้าที่หรือใช้อำนาจขัดต่อบทบัญญัติแห่งรัฐธรรมนูญหรือกฎหมาย เพื่อเสนอผู้ว่าการตรวจเงินแผ่นดินแจ้งให้คณะกรรมการป้องกันและปราบปรามการทุจริตแห่งชาติทราบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('044', 5, 'ตรวจสอบเพื่อระงับหรือยับยั้งความเสียหายที่อาจเกิดขึ้นแก่การเงินการคลังของรัฐเพื่อเสนอผู้ว่าการตรวจเงินแผ่นดิน เพื่อเสนอผลการตรวจสอบการกระทำที่ไม่เป็นไปตามกฎหมายว่าด้วยวินัยการเงินการคลังของรัฐและอาจก่อให้เกิดความเสียหายแก่การเงินการคลังของรัฐอย่างร้ายแรงต่อคณะกรรมการตรวจเงินแผ่นดินเพื่อพิจารณา');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('044', 6, 'ตรวจสอบการกระทำใด ๆ ที่มีผลให้สมาชิกสภาผู้แทนราษฎร สมาชิกวุฒิสภาหรือกรรมาธิการมีส่วนไม่ว่าทางตรงหรือทางอ้อมในการใช้งบประมาณรายจ่าย หรือตรวจสอบว่าคณะรัฐมนตรีเป็นผู้กระทำการหรืออนุมัติให้กระทำการหรือรู้ว่ามีการกระทำดังกล่าวแล้วแต่มิได้สั่งยับยั้ง หรือมีเจ้าหน้าที่ของหน่วยรับตรวจจัดทำโครงการหรืออนุมัติหรือจัดสรรเงินงบประมาณโดยรู้ว่ามีการดำเนินการดังกล่าว เพื่อแจ้งคณะกรรมการป้องกันและปราบปรามการทุจริตแห่งชาติดำเนินการตามหน้าที่และอำนาจต่อไป');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('044', 7, 'นำเสนอประเด็นและข้อมูลเกี่ยวกับการจัดทำผลผลิตของงานที่เสริมสร้างความเข้มแข็งให้กับงานตรวจสอบ (Non – Audit Product) ต่อผู้ว่าการตรวจเงินแผ่นดินเพื่อเสนอต่อคณะกรรมการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('044', 8, 'แจ้งผลการตรวจสอบและติดตามให้หน่วยงานที่เกี่ยวข้องดำเนินการตามหน้าที่และอำนาจเพื่อให้เป็นไปตามผลการตรวจสอบ ตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('044', 9, 'ติดตามผลการดำเนินงานของหน่วยรับตรวจตามข้อตรวจพบ ข้อสังเกตและข้อเสนอแนะของสำนักงานการตรวจเงินแผ่นดิน ตามหลักเกณฑ์ที่ผู้ว่าการตรวจเงินแผ่นดินกำหนด');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('044', 10, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('044', 11, 'ปฏิบัติหน้าที่อื่นตามที่คณะกรรมการตรวจเงินแผ่นดิน หรือผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('045', 1, 'ตรวจเงินแผ่นดินตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย ให้เป็นไปตามนโยบายการตรวจเงินแผ่นดิน หลักเกณฑ์มาตรฐานที่เกี่ยวกับการตรวจเงินแผ่นดิน กฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน กฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ และกฎหมายที่เกี่ยวข้อง');
