INSERT INTO mandates (dept_id, item_order, content) VALUES ('046', 2, 'ตรวจสอบผลสัมฤทธิ์และประสิทธิภาพในการใช้จ่ายเงิน และทรัพย์สินอื่นของหน่วยรับตรวจหรือที่อยู่ในความรับผิดชอบของหน่วยรับตรวจ');
