INSERT INTO mandates (dept_id, item_order, content) VALUES ('046', 5, 'จัดทำข้อเสนอแนะให้แก่หน่วยรับตรวจในการเพิ่มผลสัมฤทธิ์และประสิทธิภาพในการใช้จ่ายเงินของหน่วยรับตรวจ');
