INSERT INTO mandates (dept_id, item_order, content) VALUES ('047', 7, 'แจ้งผลการตรวจสอบและติดตามให้หน่วยงานที่เกี่ยวข้องดำเนินการตามหน้าที่และอำนาจเพื่อให้เป็นไปตามผลการตรวจสอบ ตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('047', 8, 'ติดตามผลการดำเนินงานของหน่วยรับตรวจตามข้อตรวจพบ ข้อสังเกตและข้อเสนอแนะของสำนักงานการตรวจเงินแผ่นดิน ตามหลักเกณฑ์ที่ผู้ว่าการตรวจเงินแผ่นดินกำหนด');
