INSERT INTO mandates (dept_id, item_order, content) VALUES ('095', 9, 'แจ้งผลการตรวจสอบและติดตามให้หน่วยงานที่เกี่ยวข้องดำเนินการตามหน้าที่และอำนาจเพื่อให้เป็นไปตามผลการตรวจสอบ ตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('095', 10, 'ติดตามผลการดำเนินงานของหน่วยรับตรวจตามข้อตรวจพบ ข้อสังเกตและข้อเสนอแนะของสำนักงานการตรวจเงินแผ่นดิน ตามหลักเกณฑ์ที่ผู้ว่าการตรวจเงินแผ่นดินกำหนด');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('095', 11, 'เสนอความเห็นและข้อเสนอแนะต่อสำนักงานการตรวจเงินแผ่นดินภูมิภาค พิจารณานำเสนอต่อผู้ว่าการตรวจเงินแผ่นดิน เพื่อเสนอต่อคณะกรรมการตรวจเงินแผ่นดินให้คำแนะนำหรือเสนอแนะแก่หน่วยงานของรัฐในการแก้ไขข้อบกพร่องเกี่ยวกับการใช้จ่ายเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('095', 12, 'เผยแพร่ความรู้ความเข้าใจและตอบข้อสอบถามในกรณีที่หน่วยรับตรวจสอบถามเกี่ยวกับการปฏิบัติให้ถูกต้องตามกฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน กฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ หรือในเรื่องที่อยู่ในอำนาจการตรวจสอบของผู้ว่าการตรวจเงินแผ่นดินภายในจังหวัดที่รับผิดชอบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('095', 13, 'จัดทำแผนปฏิบัติราชการประจำปีรวมทั้งติดตามประเมินผลและรายงานผลการดำเนินงานของสำนักตรวจเงินแผ่นดินจังหวัด เสนอต่อสำนักงานการตรวจเงินแผ่นดินภูมิภาค');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('095', 14, 'จัดทำคำของบประมาณประจำปีของสำนักตรวจเงินแผ่นดินจังหวัด เสนอต่อสำนักงานการตรวจเงินแผ่นดินภูมิภาค');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('095', 15, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('095', 16, 'ปฏิบัติหน้าที่อื่นตามที่คณะกรรมการตรวจเงินแผ่นดิน หรือผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('096', 1, 'ตรวจเงินแผ่นดินตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย ให้เป็นไปตามนโยบายการตรวจเงินแผ่นดิน หลักเกณฑ์มาตรฐานที่เกี่ยวกับการตรวจเงินแผ่นดิน กฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน กฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ และกฎหมายที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('096', 2, 'มีหน้าที่ตรวจสอบตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมายดังต่อไปนี้ (ก) ตรวจสอบรายงานการเงินที่หน่วยงานของรัฐส่งให้ตามกฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ (ข) ตรวจสอบการปฏิบัติตามกฎหมาย (ค) ตรวจสอบผลสัมฤทธิ์และประสิทธิภาพในการใช้จ่ายเงิน และทรัพย์สินอื่นของหน่วยรับตรวจหรือที่อยู่ในความรับผิดชอบของหน่วยรับตรวจ (ง) ตรวจสอบเพื่อระงับหรือยับยั้งความเสียหายที่อาจเกิดขึ้นแก่การเงินการคลังของรัฐ เสนอผู้ว่าการตรวจเงินแผ่นดิน เพื่อเสนอผลการตรวจสอบการกระทำที่ไม่เป็นไปตามกฎหมายว่าด้วยวินัยการเงินการคลังของรัฐและอาจก่อให้เกิดความเสียหายแก่การเงินการคลังของรัฐอย่างร้ายแรง ต่อคณะกรรมการตรวจเงินแผ่นดินเพื่อพิจารณา');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('096', 3, 'กำกับการตรวจสอบ พิจารณาผลการตรวจสอบ แจ้งผลการตรวจสอบ และติดตามผลการตรวจสอบซึ่งอยู่ในหน้าที่และอำนาจของสำนักตรวจเงินแผ่นดินจังหวัดในเขตพื้นที่รับผิดชอบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('096', 4, 'นำเสนอประเด็นและข้อมูลเกี่ยวกับการจัดทำผลผลิตของงานที่เสริมสร้างความเข้มแข็งให้กับงานตรวจสอบ (Non – Audit Product) ต่อผู้ว่าการตรวจเงินแผ่นดินเพื่อเสนอต่อคณะกรรมการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('096', 5, 'แจ้งผลการตรวจสอบและติดตามให้หน่วยงานที่เกี่ยวข้องดำเนินการตามหน้าที่และอำนาจเพื่อให้เป็นไปตามผลการตรวจสอบ ตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('096', 6, 'ติดตามผลการดำเนินงานของหน่วยรับตรวจตามข้อตรวจพบ ข้อสังเกตและข้อเสนอแนะของสำนักงานการตรวจเงินแผ่นดิน ตามหลักเกณฑ์ที่ผู้ว่าการตรวจเงินแผ่นดินกำหนด');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('096', 7, 'ศึกษา วิเคราะห์ จัดทำแผนปฏิบัติราชการและแผนการตรวจสอบประจำปีของสำนักงานการตรวจเงินแผ่นดินภูมิภาค และสำนักตรวจเงินแผ่นดินจังหวัดในเขตพื้นที่รับผิดชอบเสนอผู้ว่าการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('096', 8, 'ศึกษา วิเคราะห์ รวบรวม และจัดทำคำของบประมาณประจำปีของสำนักงานการตรวจเงินแผ่นดินภูมิภาค และสำนักตรวจเงินแผ่นดินจังหวัดในเขตพื้นที่รับผิดชอบเสนอผู้ว่าการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('096', 9, 'เผยแพร่ความรู้ความเข้าใจและตอบข้อสอบถามในกรณีที่หน่วยรับตรวจสอบถามเกี่ยวกับการปฏิบัติให้ถูกต้องตามกฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน กฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ หรือในเรื่องที่อยู่ในอำนาจการตรวจสอบของผู้ว่าการตรวจเงินแผ่นดินภายในเขตจังหวัดพื้นที่รับผิดชอบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('096', 10, 'ศึกษา วิเคราะห์สภาพปัญหาและข้อบกพร่องของหน่วยรับตรวจในการใช้จ่ายเงินแผ่นดินภายในเขตจังหวัดพื้นที่รับผิดชอบ รวบรวมเพื่อเสนอความเห็นและข้อเสนอแนะต่อผู้ว่าการตรวจเงินแผ่นดินเพื่อเสนอต่อคณะกรรมการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('096', 11, 'จัดฝึกอบรมหรือส่งเสริมการพัฒนาความรู้ ความเข้าใจ ด้านการตรวจเงินแผ่นดินให้แก่เจ้าหน้าที่และบุคลากรอื่นเพื่อสนับสนุนส่งเสริมกระบวนการตรวจสอบของสำนักงานการตรวจเงินแผ่นดินภูมิภาค และสำนักตรวจเงินแผ่นดินจังหวัดในเขตพื้นที่รับผิดชอบ และส่งเสริมสนับสนุนให้หน่วยรับตรวจรักษาวินัยการเงินการคลังของรัฐ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('096', 12, 'บริหาร จัดการ กำกับดูแล สนับสนุน ส่งเสริม และติดตามการใช้เทคโนโลยีสารสนเทศและการสื่อสาร เพื่อสนับสนุนและส่งเสริมกระบวนการตรวจสอบของสำนักงานการตรวจเงินแผ่นดินภูมิภาคและสำนักตรวจเงินแผ่นดินจังหวัดในเขตพื้นที่รับผิดชอบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('096', 13, 'จัดทำฐานข้อมูลหน่วยรับตรวจและรายงานผลการตรวจสอบของสำนักงานการตรวจเงินแผ่นดินภูมิภาค และสำนักตรวจเงินแผ่นดินจังหวัดในเขตพื้นที่รับผิดชอบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('096', 14, 'จัดทำ กำกับ ดูแล ติดตามและประเมินผลแผนปฏิบัติราชการและแผนการใช้งบประมาณ รวมถึงการปฏิบัติราชการในด้านอื่น ๆ พร้อมทั้งจัดทำรายงานผลการปฏิบัติงานระหว่างปีและรายงานผลการปฏิบัติงานประจำปีของสำนักงานการตรวจเงินแผ่นดินภูมิภาค และสำนักตรวจเงินแผ่นดินจังหวัดในเขตพื้นที่รับผิดชอบ เสนอผู้ว่าการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('096', 15, 'กำกับ ดูแล พัฒนาระบบงาน ให้คำปรึกษาแนะนำ และแก้ไขปัญหา รวมทั้งบูรณาการการปฏิบัติงานของสำนักงานการตรวจเงินแผ่นดินภูมิภาค และสำนักตรวจเงินแผ่นดินจังหวัดในเขตพื้นที่รับผิดชอบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('096', 16, 'ปฏิบัติงานสารบรรณ งานอำนวยการ และงานประสานราชการ ของสำนักงานการตรวจเงินแผ่นดินภูมิภาค รวมทั้งเป็นหน่วยงานธุรการกลางในการติดต่อราชการของสำนักงานการตรวจเงินแผ่นดินภูมิภาค และสำนักตรวจเงินแผ่นดินจังหวัดในเขตพื้นที่รับผิดชอบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('096', 17, 'ดำเนินการเกี่ยวกับการบริหารพัสดุ การจัดหา การบริการ การควบคุม ดูแล บำรุงรักษาเกี่ยวกับยานพาหนะ อาคารสถานที่และอุปกรณ์ รวมทั้งการรักษาความปลอดภัยของสำนักงานการตรวจเงินแผ่นดินภูมิภาค และสำนักตรวจเงินแผ่นดินจังหวัดในเขตพื้นที่รับผิดชอบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('096', 18, 'ดำเนินการเกี่ยวกับการเงิน การบัญชี งบประมาณ และรายงานการเงินของสำนักงานการตรวจเงินแผ่นดินภูมิภาค และสำนักตรวจเงินแผ่นดินจังหวัดในเขตพื้นที่รับผิดชอบให้สอดคล้องกับหลักการและนโยบายของการบัญชีภาครัฐ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('096', 19, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('096', 20, 'ปฏิบัติหน้าที่อื่นตามที่คณะกรรมการตรวจเงินแผ่นดิน หรือผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('097', 1, 'ตรวจเงินแผ่นดินตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย ให้เป็นไปตามนโยบายการตรวจเงินแผ่นดิน หลักเกณฑ์มาตรฐานที่เกี่ยวกับการตรวจเงินแผ่นดิน กฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน กฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ และกฎหมายที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('097', 2, 'ตรวจสอบรายงานการเงินที่หน่วยงานของรัฐส่งให้ตามกฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('097', 3, 'ตรวจสอบเงินอุดหนุนของหน่วยรับตรวจที่ได้รับเงินอุดหนุน หรือกิจการที่ได้รับเงิน หรือทรัพย์สินลงทุนจากหน่วยงานของรัฐ รัฐวิสาหกิจ หรือหน่วยงานอื่นของรัฐ ว่ามีการใช้จ่ายไปตามวัตถุประสงค์หรือไม่');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('097', 4, 'ตรวจสอบการจัดเก็บรายได้ การรับ การใช้จ่าย การใช้ประโยชน์ การเก็บรักษา และการบริหารซึ่งเงิน ทรัพย์สิน สิทธิ และผลประโยชน์ของหน่วยรับตรวจหรือที่อยู่ในความครอบครองหรืออำนาจใช้จ่ายของหน่วยรับตรวจรวมถึงการตรวจสอบอื่นตามกฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน และกฎหมายอื่นที่เกี่ยวข้องว่าเป็นไปตามกฎหมาย ระเบียบ ข้อบังคับ มติคณะรัฐมนตรี แบบแผนการปฏิบัติราชการและสัญญา');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('097', 5, 'ตรวจสอบผลสัมฤทธิ์และประสิทธิภาพในการใช้จ่ายเงิน และทรัพย์สินอื่นของหน่วยรับตรวจหรือที่อยู่ในความรับผิดชอบของหน่วยรับตรวจ ตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('097', 6, 'ตรวจสอบเพื่อระงับหรือยับยั้งความเสียหายที่อาจเกิดขึ้นแก่การเงินการคลังของรัฐเสนอความเห็นและข้อเสนอแนะต่อสำนักงานการตรวจเงินแผ่นดินภูมิภาค เสนอต่อผู้ว่าการตรวจเงินแผ่นดิน เพื่อเสนอผลการตรวจสอบการกระทำที่ไม่เป็นไปตามกฎหมายว่าด้วยวินัยการเงินการคลังของรัฐและอาจก่อให้เกิดความเสียหายแก่การเงินการคลังของรัฐอย่างร้ายแรง ต่อคณะกรรมการตรวจเงินแผ่นดินเพื่อพิจารณา');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('097', 7, 'ตรวจสอบกรณีผลการตรวจสอบตามหน้าที่และอำนาจ พบข้อบกพร่องว่าหน่วยรับตรวจไม่ปฏิบัติตามกฎหมาย ระเบียบ ข้อบังคับ มติคณะรัฐมนตรี แบบแผนการปฏิบัติราชการและสัญญา');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('097', 8, 'นำเสนอประเด็นและข้อมูลเกี่ยวกับการจัดทำผลผลิตของงานที่เสริมสร้างความเข้มแข็งให้กับงานตรวจสอบ (Non - Audit Product) ต่อสำนักงานการตรวจเงินแผ่นดินภูมิภาค เสนอผู้ว่าการตรวจเงินแผ่นดินเพื่อเสนอต่อคณะกรรมการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('097', 9, 'แจ้งผลการตรวจสอบและติดตามให้หน่วยงานที่เกี่ยวข้องดำเนินการตามหน้าที่และอำนาจเพื่อให้เป็นไปตามผลการตรวจสอบ ตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('097', 10, 'ติดตามผลการดำเนินงานของหน่วยรับตรวจตามข้อตรวจพบ ข้อสังเกตและข้อเสนอแนะของสำนักงานการตรวจเงินแผ่นดิน ตามหลักเกณฑ์ที่ผู้ว่าการตรวจเงินแผ่นดินกำหนด');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('097', 11, 'เสนอความเห็นและข้อเสนอแนะต่อสำนักงานการตรวจเงินแผ่นดินภูมิภาค พิจารณานำเสนอต่อผู้ว่าการตรวจเงินแผ่นดิน เพื่อเสนอต่อคณะกรรมการตรวจเงินแผ่นดินให้คำแนะนำหรือเสนอแนะแก่หน่วยงานของรัฐในการแก้ไขข้อบกพร่องเกี่ยวกับการใช้จ่ายเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('097', 12, 'เผยแพร่ความรู้ความเข้าใจและตอบข้อสอบถามในกรณีที่หน่วยรับตรวจสอบถามเกี่ยวกับการปฏิบัติให้ถูกต้องตามกฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน กฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ หรือในเรื่องที่อยู่ในอำนาจการตรวจสอบของผู้ว่าการตรวจเงินแผ่นดินภายในจังหวัดที่รับผิดชอบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('097', 13, 'จัดทำแผนปฏิบัติราชการประจำปีรวมทั้งติดตามประเมินผลและรายงานผลการดำเนินงานของสำนักตรวจเงินแผ่นดินจังหวัด เสนอต่อสำนักงานการตรวจเงินแผ่นดินภูมิภาค');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('097', 14, 'จัดทำคำของบประมาณประจำปีของสำนักตรวจเงินแผ่นดินจังหวัด เสนอต่อสำนักงานการตรวจเงินแผ่นดินภูมิภาค');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('097', 15, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('097', 16, 'ปฏิบัติหน้าที่อื่นตามที่คณะกรรมการตรวจเงินแผ่นดิน หรือผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('098', 1, 'ตรวจเงินแผ่นดินตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย ให้เป็นไปตามนโยบายการตรวจเงินแผ่นดิน หลักเกณฑ์มาตรฐานที่เกี่ยวกับการตรวจเงินแผ่นดิน กฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน กฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ และกฎหมายที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('098', 2, 'ตรวจสอบรายงานการเงินที่หน่วยงานของรัฐส่งให้ตามกฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('098', 3, 'ตรวจสอบเงินอุดหนุนของหน่วยรับตรวจที่ได้รับเงินอุดหนุน หรือกิจการที่ได้รับเงิน หรือทรัพย์สินลงทุนจากหน่วยงานของรัฐ รัฐวิสาหกิจ หรือหน่วยงานอื่นของรัฐ ว่ามีการใช้จ่ายไปตามวัตถุประสงค์หรือไม่');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('098', 4, 'ตรวจสอบการจัดเก็บรายได้ การรับ การใช้จ่าย การใช้ประโยชน์ การเก็บรักษา และการบริหารซึ่งเงิน ทรัพย์สิน สิทธิ และผลประโยชน์ของหน่วยรับตรวจหรือที่อยู่ในความครอบครองหรืออำนาจใช้จ่ายของหน่วยรับตรวจรวมถึงการตรวจสอบอื่นตามกฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน และกฎหมายอื่นที่เกี่ยวข้องว่าเป็นไปตามกฎหมาย ระเบียบ ข้อบังคับ มติคณะรัฐมนตรี แบบแผนการปฏิบัติราชการและสัญญา');
