INSERT INTO mandates (dept_id, item_order, content) VALUES ('110', 11, 'เสนอความเห็นและข้อเสนอแนะต่อสำนักงานการตรวจเงินแผ่นดินภูมิภาค พิจารณานำเสนอต่อผู้ว่าการตรวจเงินแผ่นดิน เพื่อเสนอต่อคณะกรรมการตรวจเงินแผ่นดินให้คำแนะนำหรือเสนอแนะแก่หน่วยงานของรัฐในการแก้ไขข้อบกพร่องเกี่ยวกับการใช้จ่ายเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('110', 12, 'เผยแพร่ความรู้ความเข้าใจและตอบข้อสอบถามในกรณีที่หน่วยรับตรวจสอบถามเกี่ยวกับการปฏิบัติให้ถูกต้องตามกฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน กฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ หรือในเรื่องที่อยู่ในอำนาจการตรวจสอบของผู้ว่าการตรวจเงินแผ่นดินภายในจังหวัดที่รับผิดชอบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('110', 13, 'จัดทำแผนปฏิบัติราชการประจำปีรวมทั้งติดตามประเมินผลและรายงานผลการดำเนินงานของสำนักตรวจเงินแผ่นดินจังหวัด เสนอต่อสำนักงานการตรวจเงินแผ่นดินภูมิภาค');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('110', 14, 'จัดทำคำของบประมาณประจำปีของสำนักตรวจเงินแผ่นดินจังหวัด เสนอต่อสำนักงานการตรวจเงินแผ่นดินภูมิภาค');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('110', 15, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('110', 16, 'ปฏิบัติหน้าที่อื่นตามที่คณะกรรมการตรวจเงินแผ่นดิน หรือผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('111', 1, 'ตรวจเงินแผ่นดินตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย ให้เป็นไปตามนโยบายการตรวจเงินแผ่นดิน หลักเกณฑ์มาตรฐานที่เกี่ยวกับการตรวจเงินแผ่นดิน กฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน กฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ และกฎหมายที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('111', 2, 'ตรวจสอบรายงานการเงินที่หน่วยงานของรัฐส่งให้ตามกฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('111', 3, 'ตรวจสอบเงินอุดหนุนของหน่วยรับตรวจที่ได้รับเงินอุดหนุน หรือกิจการที่ได้รับเงิน หรือทรัพย์สินลงทุนจากหน่วยงานของรัฐ รัฐวิสาหกิจ หรือหน่วยงานอื่นของรัฐ ว่ามีการใช้จ่ายไปตามวัตถุประสงค์หรือไม่');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('111', 4, 'ตรวจสอบการจัดเก็บรายได้ การรับ การใช้จ่าย การใช้ประโยชน์ การเก็บรักษา และการบริหารซึ่งเงิน ทรัพย์สิน สิทธิ และผลประโยชน์ของหน่วยรับตรวจหรือที่อยู่ในความครอบครองหรืออำนาจใช้จ่ายของหน่วยรับตรวจรวมถึงการตรวจสอบอื่นตามกฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน และกฎหมายอื่นที่เกี่ยวข้องว่าเป็นไปตามกฎหมาย ระเบียบ ข้อบังคับ มติคณะรัฐมนตรี แบบแผนการปฏิบัติราชการและสัญญา');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('111', 5, 'ตรวจสอบผลสัมฤทธิ์และประสิทธิภาพในการใช้จ่ายเงิน และทรัพย์สินอื่นของหน่วยรับตรวจหรือที่อยู่ในความรับผิดชอบของหน่วยรับตรวจ ตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('111', 6, 'ตรวจสอบเพื่อระงับหรือยับยั้งความเสียหายที่อาจเกิดขึ้นแก่การเงินการคลังของรัฐเสนอความเห็นและข้อเสนอแนะต่อสำนักงานการตรวจเงินแผ่นดินภูมิภาค เสนอต่อผู้ว่าการตรวจเงินแผ่นดิน เพื่อเสนอผลการตรวจสอบการกระทำที่ไม่เป็นไปตามกฎหมายว่าด้วยวินัยการเงินการคลังของรัฐและอาจก่อให้เกิดความเสียหายแก่การเงินการคลังของรัฐอย่างร้ายแรง ต่อคณะกรรมการตรวจเงินแผ่นดินเพื่อพิจารณา');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('111', 7, 'ตรวจสอบกรณีผลการตรวจสอบตามหน้าที่และอำนาจ พบข้อบกพร่องว่าหน่วยรับตรวจไม่ปฏิบัติตามกฎหมาย ระเบียบ ข้อบังคับ มติคณะรัฐมนตรี แบบแผนการปฏิบัติราชการและสัญญา');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('111', 8, 'นำเสนอประเด็นและข้อมูลเกี่ยวกับการจัดทำผลผลิตของงานที่เสริมสร้างความเข้มแข็งให้กับงานตรวจสอบ (Non - Audit Product) ต่อสำนักงานการตรวจเงินแผ่นดินภูมิภาค เสนอผู้ว่าการตรวจเงินแผ่นดินเพื่อเสนอต่อคณะกรรมการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('111', 9, 'แจ้งผลการตรวจสอบและติดตามให้หน่วยงานที่เกี่ยวข้องดำเนินการตามหน้าที่และอำนาจเพื่อให้เป็นไปตามผลการตรวจสอบ ตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('111', 10, 'ติดตามผลการดำเนินงานของหน่วยรับตรวจตามข้อตรวจพบ ข้อสังเกตและข้อเสนอแนะของสำนักงานการตรวจเงินแผ่นดิน ตามหลักเกณฑ์ที่ผู้ว่าการตรวจเงินแผ่นดินกำหนด');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('111', 11, 'เสนอความเห็นและข้อเสนอแนะต่อสำนักงานการตรวจเงินแผ่นดินภูมิภาค พิจารณานำเสนอต่อผู้ว่าการตรวจเงินแผ่นดิน เพื่อเสนอต่อคณะกรรมการตรวจเงินแผ่นดินให้คำแนะนำหรือเสนอแนะแก่หน่วยงานของรัฐในการแก้ไขข้อบกพร่องเกี่ยวกับการใช้จ่ายเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('111', 12, 'เผยแพร่ความรู้ความเข้าใจและตอบข้อสอบถามในกรณีที่หน่วยรับตรวจสอบถามเกี่ยวกับการปฏิบัติให้ถูกต้องตามกฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน กฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ หรือในเรื่องที่อยู่ในอำนาจการตรวจสอบของผู้ว่าการตรวจเงินแผ่นดินภายในจังหวัดที่รับผิดชอบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('111', 13, 'จัดทำแผนปฏิบัติราชการประจำปีรวมทั้งติดตามประเมินผลและรายงานผลการดำเนินงานของสำนักตรวจเงินแผ่นดินจังหวัด เสนอต่อสำนักงานการตรวจเงินแผ่นดินภูมิภาค');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('111', 14, 'จัดทำคำของบประมาณประจำปีของสำนักตรวจเงินแผ่นดินจังหวัด เสนอต่อสำนักงานการตรวจเงินแผ่นดินภูมิภาค');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('111', 15, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('111', 16, 'ปฏิบัติหน้าที่อื่นตามที่คณะกรรมการตรวจเงินแผ่นดิน หรือผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('112', 1, 'ตรวจเงินแผ่นดินตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย ให้เป็นไปตามนโยบายการตรวจเงินแผ่นดิน หลักเกณฑ์มาตรฐานที่เกี่ยวกับการตรวจเงินแผ่นดิน กฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน กฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ และกฎหมายที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('112', 2, 'มีหน้าที่ตรวจสอบตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมายดังต่อไปนี้ (ก) ตรวจสอบรายงานการเงินที่หน่วยงานของรัฐส่งให้ตามกฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ (ข) ตรวจสอบการปฏิบัติตามกฎหมาย (ค) ตรวจสอบผลสัมฤทธิ์และประสิทธิภาพในการใช้จ่ายเงิน และทรัพย์สินอื่นของหน่วยรับตรวจหรือที่อยู่ในความรับผิดชอบของหน่วยรับตรวจ (ง) ตรวจสอบเพื่อระงับหรือยับยั้งความเสียหายที่อาจเกิดขึ้นแก่การเงินการคลังของรัฐ เสนอผู้ว่าการตรวจเงินแผ่นดิน เพื่อเสนอผลการตรวจสอบการกระทำที่ไม่เป็นไปตามกฎหมายว่าด้วยวินัยการเงินการคลังของรัฐและอาจก่อให้เกิดความเสียหายแก่การเงินการคลังของรัฐอย่างร้ายแรง ต่อคณะกรรมการตรวจเงินแผ่นดินเพื่อพิจารณา');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('112', 3, 'กำกับการตรวจสอบ พิจารณาผลการตรวจสอบ แจ้งผลการตรวจสอบ และติดตามผลการตรวจสอบซึ่งอยู่ในหน้าที่และอำนาจของสำนักตรวจเงินแผ่นดินจังหวัดในเขตพื้นที่รับผิดชอบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('112', 4, 'นำเสนอประเด็นและข้อมูลเกี่ยวกับการจัดทำผลผลิตของงานที่เสริมสร้างความเข้มแข็งให้กับงานตรวจสอบ (Non – Audit Product) ต่อผู้ว่าการตรวจเงินแผ่นดินเพื่อเสนอต่อคณะกรรมการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('112', 5, 'แจ้งผลการตรวจสอบและติดตามให้หน่วยงานที่เกี่ยวข้องดำเนินการตามหน้าที่และอำนาจเพื่อให้เป็นไปตามผลการตรวจสอบ ตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('112', 6, 'ติดตามผลการดำเนินงานของหน่วยรับตรวจตามข้อตรวจพบ ข้อสังเกตและข้อเสนอแนะของสำนักงานการตรวจเงินแผ่นดิน ตามหลักเกณฑ์ที่ผู้ว่าการตรวจเงินแผ่นดินกำหนด');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('112', 7, 'ศึกษา วิเคราะห์ จัดทำแผนปฏิบัติราชการและแผนการตรวจสอบประจำปีของสำนักงานการตรวจเงินแผ่นดินภูมิภาค และสำนักตรวจเงินแผ่นดินจังหวัดในเขตพื้นที่รับผิดชอบเสนอผู้ว่าการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('112', 8, 'ศึกษา วิเคราะห์ รวบรวม และจัดทำคำของบประมาณประจำปีของสำนักงานการตรวจเงินแผ่นดินภูมิภาค และสำนักตรวจเงินแผ่นดินจังหวัดในเขตพื้นที่รับผิดชอบเสนอผู้ว่าการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('112', 9, 'เผยแพร่ความรู้ความเข้าใจและตอบข้อสอบถามในกรณีที่หน่วยรับตรวจสอบถามเกี่ยวกับการปฏิบัติให้ถูกต้องตามกฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน กฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ หรือในเรื่องที่อยู่ในอำนาจการตรวจสอบของผู้ว่าการตรวจเงินแผ่นดินภายในเขตจังหวัดพื้นที่รับผิดชอบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('112', 10, 'ศึกษา วิเคราะห์สภาพปัญหาและข้อบกพร่องของหน่วยรับตรวจในการใช้จ่ายเงินแผ่นดินภายในเขตจังหวัดพื้นที่รับผิดชอบ รวบรวมเพื่อเสนอความเห็นและข้อเสนอแนะต่อผู้ว่าการตรวจเงินแผ่นดินเพื่อเสนอต่อคณะกรรมการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('112', 11, 'จัดฝึกอบรมหรือส่งเสริมการพัฒนาความรู้ ความเข้าใจ ด้านการตรวจเงินแผ่นดินให้แก่เจ้าหน้าที่และบุคลากรอื่นเพื่อสนับสนุนส่งเสริมกระบวนการตรวจสอบของสำนักงานการตรวจเงินแผ่นดินภูมิภาค และสำนักตรวจเงินแผ่นดินจังหวัดในเขตพื้นที่รับผิดชอบ และส่งเสริมสนับสนุนให้หน่วยรับตรวจรักษาวินัยการเงินการคลังของรัฐ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('112', 12, 'บริหาร จัดการ กำกับดูแล สนับสนุน ส่งเสริม และติดตามการใช้เทคโนโลยีสารสนเทศและการสื่อสาร เพื่อสนับสนุนและส่งเสริมกระบวนการตรวจสอบของสำนักงานการตรวจเงินแผ่นดินภูมิภาคและสำนักตรวจเงินแผ่นดินจังหวัดในเขตพื้นที่รับผิดชอบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('112', 13, 'จัดทำฐานข้อมูลหน่วยรับตรวจและรายงานผลการตรวจสอบของสำนักงานการตรวจเงินแผ่นดินภูมิภาค และสำนักตรวจเงินแผ่นดินจังหวัดในเขตพื้นที่รับผิดชอบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('112', 14, 'จัดทำ กำกับ ดูแล ติดตามและประเมินผลแผนปฏิบัติราชการและแผนการใช้งบประมาณ รวมถึงการปฏิบัติราชการในด้านอื่น ๆ พร้อมทั้งจัดทำรายงานผลการปฏิบัติงานระหว่างปีและรายงานผลการปฏิบัติงานประจำปีของสำนักงานการตรวจเงินแผ่นดินภูมิภาค และสำนักตรวจเงินแผ่นดินจังหวัดในเขตพื้นที่รับผิดชอบ เสนอผู้ว่าการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('112', 15, 'กำกับ ดูแล พัฒนาระบบงาน ให้คำปรึกษาแนะนำ และแก้ไขปัญหา รวมทั้งบูรณาการการปฏิบัติงานของสำนักงานการตรวจเงินแผ่นดินภูมิภาค และสำนักตรวจเงินแผ่นดินจังหวัดในเขตพื้นที่รับผิดชอบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('112', 16, 'ปฏิบัติงานสารบรรณ งานอำนวยการ และงานประสานราชการ ของสำนักงานการตรวจเงินแผ่นดินภูมิภาค รวมทั้งเป็นหน่วยงานธุรการกลางในการติดต่อราชการของสำนักงานการตรวจเงินแผ่นดินภูมิภาค และสำนักตรวจเงินแผ่นดินจังหวัดในเขตพื้นที่รับผิดชอบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('112', 17, 'ดำเนินการเกี่ยวกับการบริหารพัสดุ การจัดหา การบริการ การควบคุม ดูแล บำรุงรักษาเกี่ยวกับยานพาหนะ อาคารสถานที่และอุปกรณ์ รวมทั้งการรักษาความปลอดภัยของสำนักงานการตรวจเงินแผ่นดินภูมิภาค และสำนักตรวจเงินแผ่นดินจังหวัดในเขตพื้นที่รับผิดชอบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('112', 18, 'ดำเนินการเกี่ยวกับการเงิน การบัญชี งบประมาณ และรายงานการเงินของสำนักงานการตรวจเงินแผ่นดินภูมิภาค และสำนักตรวจเงินแผ่นดินจังหวัดในเขตพื้นที่รับผิดชอบให้สอดคล้องกับหลักการและนโยบายของการบัญชีภาครัฐ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('112', 19, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('112', 20, 'ปฏิบัติหน้าที่อื่นตามที่คณะกรรมการตรวจเงินแผ่นดิน หรือผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('113', 1, 'ตรวจเงินแผ่นดินตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย ให้เป็นไปตามนโยบายการตรวจเงินแผ่นดิน หลักเกณฑ์มาตรฐานที่เกี่ยวกับการตรวจเงินแผ่นดิน กฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน กฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ และกฎหมายที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('113', 2, 'ตรวจสอบรายงานการเงินที่หน่วยงานของรัฐส่งให้ตามกฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('113', 3, 'ตรวจสอบเงินอุดหนุนของหน่วยรับตรวจที่ได้รับเงินอุดหนุน หรือกิจการที่ได้รับเงิน หรือทรัพย์สินลงทุนจากหน่วยงานของรัฐ รัฐวิสาหกิจ หรือหน่วยงานอื่นของรัฐ ว่ามีการใช้จ่ายไปตามวัตถุประสงค์หรือไม่');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('113', 4, 'ตรวจสอบการจัดเก็บรายได้ การรับ การใช้จ่าย การใช้ประโยชน์ การเก็บรักษา และการบริหารซึ่งเงิน ทรัพย์สิน สิทธิ และผลประโยชน์ของหน่วยรับตรวจหรือที่อยู่ในความครอบครองหรืออำนาจใช้จ่ายของหน่วยรับตรวจรวมถึงการตรวจสอบอื่นตามกฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน และกฎหมายอื่นที่เกี่ยวข้องว่าเป็นไปตามกฎหมาย ระเบียบ ข้อบังคับ มติคณะรัฐมนตรี แบบแผนการปฏิบัติราชการและสัญญา');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('113', 5, 'ตรวจสอบผลสัมฤทธิ์และประสิทธิภาพในการใช้จ่ายเงิน และทรัพย์สินอื่นของหน่วยรับตรวจหรือที่อยู่ในความรับผิดชอบของหน่วยรับตรวจ ตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('113', 6, 'ตรวจสอบเพื่อระงับหรือยับยั้งความเสียหายที่อาจเกิดขึ้นแก่การเงินการคลังของรัฐเสนอความเห็นและข้อเสนอแนะต่อสำนักงานการตรวจเงินแผ่นดินภูมิภาค เสนอต่อผู้ว่าการตรวจเงินแผ่นดิน เพื่อเสนอผลการตรวจสอบการกระทำที่ไม่เป็นไปตามกฎหมายว่าด้วยวินัยการเงินการคลังของรัฐและอาจก่อให้เกิดความเสียหายแก่การเงินการคลังของรัฐอย่างร้ายแรง ต่อคณะกรรมการตรวจเงินแผ่นดินเพื่อพิจารณา');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('113', 7, 'ตรวจสอบกรณีผลการตรวจสอบตามหน้าที่และอำนาจ พบข้อบกพร่องว่าหน่วยรับตรวจไม่ปฏิบัติตามกฎหมาย ระเบียบ ข้อบังคับ มติคณะรัฐมนตรี แบบแผนการปฏิบัติราชการและสัญญา');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('113', 8, 'นำเสนอประเด็นและข้อมูลเกี่ยวกับการจัดทำผลผลิตของงานที่เสริมสร้างความเข้มแข็งให้กับงานตรวจสอบ (Non - Audit Product) ต่อสำนักงานการตรวจเงินแผ่นดินภูมิภาค เสนอผู้ว่าการตรวจเงินแผ่นดินเพื่อเสนอต่อคณะกรรมการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('113', 9, 'แจ้งผลการตรวจสอบและติดตามให้หน่วยงานที่เกี่ยวข้องดำเนินการตามหน้าที่และอำนาจเพื่อให้เป็นไปตามผลการตรวจสอบ ตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('113', 10, 'ติดตามผลการดำเนินงานของหน่วยรับตรวจตามข้อตรวจพบ ข้อสังเกตและข้อเสนอแนะของสำนักงานการตรวจเงินแผ่นดิน ตามหลักเกณฑ์ที่ผู้ว่าการตรวจเงินแผ่นดินกำหนด');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('113', 11, 'เสนอความเห็นและข้อเสนอแนะต่อสำนักงานการตรวจเงินแผ่นดินภูมิภาค พิจารณานำเสนอต่อผู้ว่าการตรวจเงินแผ่นดิน เพื่อเสนอต่อคณะกรรมการตรวจเงินแผ่นดินให้คำแนะนำหรือเสนอแนะแก่หน่วยงานของรัฐในการแก้ไขข้อบกพร่องเกี่ยวกับการใช้จ่ายเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('113', 12, 'เผยแพร่ความรู้ความเข้าใจและตอบข้อสอบถามในกรณีที่หน่วยรับตรวจสอบถามเกี่ยวกับการปฏิบัติให้ถูกต้องตามกฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน กฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ หรือในเรื่องที่อยู่ในอำนาจการตรวจสอบของผู้ว่าการตรวจเงินแผ่นดินภายในจังหวัดที่รับผิดชอบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('113', 13, 'จัดทำแผนปฏิบัติราชการประจำปีรวมทั้งติดตามประเมินผลและรายงานผลการดำเนินงานของสำนักตรวจเงินแผ่นดินจังหวัด เสนอต่อสำนักงานการตรวจเงินแผ่นดินภูมิภาค');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('113', 14, 'จัดทำคำของบประมาณประจำปีของสำนักตรวจเงินแผ่นดินจังหวัด เสนอต่อสำนักงานการตรวจเงินแผ่นดินภูมิภาค');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('113', 15, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('113', 16, 'ปฏิบัติหน้าที่อื่นตามที่คณะกรรมการตรวจเงินแผ่นดิน หรือผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('114', 1, 'ตรวจเงินแผ่นดินตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย ให้เป็นไปตามนโยบายการตรวจเงินแผ่นดิน หลักเกณฑ์มาตรฐานที่เกี่ยวกับการตรวจเงินแผ่นดิน กฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน กฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ และกฎหมายที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('114', 2, 'ตรวจสอบรายงานการเงินที่หน่วยงานของรัฐส่งให้ตามกฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('114', 3, 'ตรวจสอบเงินอุดหนุนของหน่วยรับตรวจที่ได้รับเงินอุดหนุน หรือกิจการที่ได้รับเงิน หรือทรัพย์สินลงทุนจากหน่วยงานของรัฐ รัฐวิสาหกิจ หรือหน่วยงานอื่นของรัฐ ว่ามีการใช้จ่ายไปตามวัตถุประสงค์หรือไม่');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('114', 4, 'ตรวจสอบการจัดเก็บรายได้ การรับ การใช้จ่าย การใช้ประโยชน์ การเก็บรักษา และการบริหารซึ่งเงิน ทรัพย์สิน สิทธิ และผลประโยชน์ของหน่วยรับตรวจหรือที่อยู่ในความครอบครองหรืออำนาจใช้จ่ายของหน่วยรับตรวจรวมถึงการตรวจสอบอื่นตามกฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน และกฎหมายอื่นที่เกี่ยวข้องว่าเป็นไปตามกฎหมาย ระเบียบ ข้อบังคับ มติคณะรัฐมนตรี แบบแผนการปฏิบัติราชการและสัญญา');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('114', 5, 'ตรวจสอบผลสัมฤทธิ์และประสิทธิภาพในการใช้จ่ายเงิน และทรัพย์สินอื่นของหน่วยรับตรวจหรือที่อยู่ในความรับผิดชอบของหน่วยรับตรวจ ตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('114', 6, 'ตรวจสอบเพื่อระงับหรือยับยั้งความเสียหายที่อาจเกิดขึ้นแก่การเงินการคลังของรัฐเสนอความเห็นและข้อเสนอแนะต่อสำนักงานการตรวจเงินแผ่นดินภูมิภาค เสนอต่อผู้ว่าการตรวจเงินแผ่นดิน เพื่อเสนอผลการตรวจสอบการกระทำที่ไม่เป็นไปตามกฎหมายว่าด้วยวินัยการเงินการคลังของรัฐและอาจก่อให้เกิดความเสียหายแก่การเงินการคลังของรัฐอย่างร้ายแรง ต่อคณะกรรมการตรวจเงินแผ่นดินเพื่อพิจารณา');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('114', 7, 'ตรวจสอบกรณีผลการตรวจสอบตามหน้าที่และอำนาจ พบข้อบกพร่องว่าหน่วยรับตรวจไม่ปฏิบัติตามกฎหมาย ระเบียบ ข้อบังคับ มติคณะรัฐมนตรี แบบแผนการปฏิบัติราชการและสัญญา');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('114', 8, 'นำเสนอประเด็นและข้อมูลเกี่ยวกับการจัดทำผลผลิตของงานที่เสริมสร้างความเข้มแข็งให้กับงานตรวจสอบ (Non - Audit Product) ต่อสำนักงานการตรวจเงินแผ่นดินภูมิภาค เสนอผู้ว่าการตรวจเงินแผ่นดินเพื่อเสนอต่อคณะกรรมการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('114', 9, 'แจ้งผลการตรวจสอบและติดตามให้หน่วยงานที่เกี่ยวข้องดำเนินการตามหน้าที่และอำนาจเพื่อให้เป็นไปตามผลการตรวจสอบ ตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('114', 10, 'ติดตามผลการดำเนินงานของหน่วยรับตรวจตามข้อตรวจพบ ข้อสังเกตและข้อเสนอแนะของสำนักงานการตรวจเงินแผ่นดิน ตามหลักเกณฑ์ที่ผู้ว่าการตรวจเงินแผ่นดินกำหนด');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('114', 11, 'เสนอความเห็นและข้อเสนอแนะต่อสำนักงานการตรวจเงินแผ่นดินภูมิภาค พิจารณานำเสนอต่อผู้ว่าการตรวจเงินแผ่นดิน เพื่อเสนอต่อคณะกรรมการตรวจเงินแผ่นดินให้คำแนะนำหรือเสนอแนะแก่หน่วยงานของรัฐในการแก้ไขข้อบกพร่องเกี่ยวกับการใช้จ่ายเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('114', 12, 'เผยแพร่ความรู้ความเข้าใจและตอบข้อสอบถามในกรณีที่หน่วยรับตรวจสอบถามเกี่ยวกับการปฏิบัติให้ถูกต้องตามกฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน กฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ หรือในเรื่องที่อยู่ในอำนาจการตรวจสอบของผู้ว่าการตรวจเงินแผ่นดินภายในจังหวัดที่รับผิดชอบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('114', 13, 'จัดทำแผนปฏิบัติราชการประจำปีรวมทั้งติดตามประเมินผลและรายงานผลการดำเนินงานของสำนักตรวจเงินแผ่นดินจังหวัด เสนอต่อสำนักงานการตรวจเงินแผ่นดินภูมิภาค');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('114', 14, 'จัดทำคำของบประมาณประจำปีของสำนักตรวจเงินแผ่นดินจังหวัด เสนอต่อสำนักงานการตรวจเงินแผ่นดินภูมิภาค');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('114', 15, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('114', 16, 'ปฏิบัติหน้าที่อื่นตามที่คณะกรรมการตรวจเงินแผ่นดิน หรือผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('115', 1, 'ตรวจเงินแผ่นดินตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย ให้เป็นไปตามนโยบายการตรวจเงินแผ่นดิน หลักเกณฑ์มาตรฐานที่เกี่ยวกับการตรวจเงินแผ่นดิน กฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน กฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ และกฎหมายที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('115', 2, 'ตรวจสอบรายงานการเงินที่หน่วยงานของรัฐส่งให้ตามกฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('115', 3, 'ตรวจสอบเงินอุดหนุนของหน่วยรับตรวจที่ได้รับเงินอุดหนุน หรือกิจการที่ได้รับเงิน หรือทรัพย์สินลงทุนจากหน่วยงานของรัฐ รัฐวิสาหกิจ หรือหน่วยงานอื่นของรัฐ ว่ามีการใช้จ่ายไปตามวัตถุประสงค์หรือไม่');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('115', 4, 'ตรวจสอบการจัดเก็บรายได้ การรับ การใช้จ่าย การใช้ประโยชน์ การเก็บรักษา และการบริหารซึ่งเงิน ทรัพย์สิน สิทธิ และผลประโยชน์ของหน่วยรับตรวจหรือที่อยู่ในความครอบครองหรืออำนาจใช้จ่ายของหน่วยรับตรวจรวมถึงการตรวจสอบอื่นตามกฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน และกฎหมายอื่นที่เกี่ยวข้องว่าเป็นไปตามกฎหมาย ระเบียบ ข้อบังคับ มติคณะรัฐมนตรี แบบแผนการปฏิบัติราชการและสัญญา');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('115', 5, 'ตรวจสอบผลสัมฤทธิ์และประสิทธิภาพในการใช้จ่ายเงิน และทรัพย์สินอื่นของหน่วยรับตรวจหรือที่อยู่ในความรับผิดชอบของหน่วยรับตรวจ ตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('115', 6, 'ตรวจสอบเพื่อระงับหรือยับยั้งความเสียหายที่อาจเกิดขึ้นแก่การเงินการคลังของรัฐเสนอความเห็นและข้อเสนอแนะต่อสำนักงานการตรวจเงินแผ่นดินภูมิภาค เสนอต่อผู้ว่าการตรวจเงินแผ่นดิน เพื่อเสนอผลการตรวจสอบการกระทำที่ไม่เป็นไปตามกฎหมายว่าด้วยวินัยการเงินการคลังของรัฐและอาจก่อให้เกิดความเสียหายแก่การเงินการคลังของรัฐอย่างร้ายแรง ต่อคณะกรรมการตรวจเงินแผ่นดินเพื่อพิจารณา');
