INSERT INTO mandates (dept_id, item_order, content) VALUES ('133', 1, 'ตรวจเงินแผ่นดินตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย ให้เป็นไปตามนโยบายการตรวจเงินแผ่นดิน หลักเกณฑ์มาตรฐานที่เกี่ยวกับการตรวจเงินแผ่นดิน กฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน กฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ และกฎหมายที่เกี่ยวข้อง');
