INSERT INTO mandates (dept_id, item_order, content) VALUES ('141', 7, 'ตรวจสอบกรณีผลการตรวจสอบตามหน้าที่และอำนาจ พบข้อบกพร่องว่าหน่วยรับตรวจไม่ปฏิบัติตามกฎหมาย ระเบียบ ข้อบังคับ มติคณะรัฐมนตรี แบบแผนการปฏิบัติราชการและสัญญา');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('141', 8, 'นำเสนอประเด็นและข้อมูลเกี่ยวกับการจัดทำผลผลิตของงานที่เสริมสร้างความเข้มแข็งให้กับงานตรวจสอบ (Non - Audit Product) ต่อสำนักงานการตรวจเงินแผ่นดินภูมิภาค เสนอผู้ว่าการตรวจเงินแผ่นดินเพื่อเสนอต่อคณะกรรมการตรวจเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('141', 9, 'แจ้งผลการตรวจสอบและติดตามให้หน่วยงานที่เกี่ยวข้องดำเนินการตามหน้าที่และอำนาจเพื่อให้เป็นไปตามผลการตรวจสอบ ตามที่ผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('141', 10, 'ติดตามผลการดำเนินงานของหน่วยรับตรวจตามข้อตรวจพบ ข้อสังเกตและข้อเสนอแนะของสำนักงานการตรวจเงินแผ่นดิน ตามหลักเกณฑ์ที่ผู้ว่าการตรวจเงินแผ่นดินกำหนด');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('141', 11, 'เสนอความเห็นและข้อเสนอแนะต่อสำนักงานการตรวจเงินแผ่นดินภูมิภาค พิจารณานำเสนอต่อผู้ว่าการตรวจเงินแผ่นดิน เพื่อเสนอต่อคณะกรรมการตรวจเงินแผ่นดินให้คำแนะนำหรือเสนอแนะแก่หน่วยงานของรัฐในการแก้ไขข้อบกพร่องเกี่ยวกับการใช้จ่ายเงินแผ่นดิน');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('141', 12, 'เผยแพร่ความรู้ความเข้าใจและตอบข้อสอบถามในกรณีที่หน่วยรับตรวจสอบถามเกี่ยวกับการปฏิบัติให้ถูกต้องตามกฎหมายประกอบรัฐธรรมนูญว่าด้วยการตรวจเงินแผ่นดิน กฎหมายว่าด้วยวินัยการเงินการคลังของรัฐ หรือในเรื่องที่อยู่ในอำนาจการตรวจสอบของผู้ว่าการตรวจเงินแผ่นดินภายในจังหวัดที่รับผิดชอบ');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('141', 13, 'จัดทำแผนปฏิบัติราชการประจำปีรวมทั้งติดตามประเมินผลและรายงานผลการดำเนินงานของสำนักตรวจเงินแผ่นดินจังหวัด เสนอต่อสำนักงานการตรวจเงินแผ่นดินภูมิภาค');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('141', 14, 'จัดทำคำของบประมาณประจำปีของสำนักตรวจเงินแผ่นดินจังหวัด เสนอต่อสำนักงานการตรวจเงินแผ่นดินภูมิภาค');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('141', 15, 'ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของส่วนราชการภายในอื่นที่เกี่ยวข้อง');
INSERT INTO mandates (dept_id, item_order, content) VALUES ('141', 16, 'ปฏิบัติหน้าที่อื่นตามที่คณะกรรมการตรวจเงินแผ่นดิน หรือผู้ว่าการตรวจเงินแผ่นดินมอบหมาย');